/// Access class for a village in the shared world. Ownership is deliberately
/// simulation state so every action can enforce it independently of server
/// routing and UI visibility.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum VillageKind {
    #[default]
    Global,
    Personal,
}

/// Durable founding contract, independent from who may control the village.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum VillageScale {
    #[default]
    Personal,
    Communal,
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct WorldState {
    pub world_seed: u32,
    pub colonies: Vec<ColonyRuntime>,
    /// Canonical mutable terrain and ecology for the shared world. Colony-local
    /// `world_tiles` and `fish_habitats` remain persisted compatibility/view caches:
    /// they are hydrated from this ledger before simulation and projected back only
    /// for coordinates that colony has mapped. Fog and contact never enter this type.
    pub shared_spatial: SharedSpatialState,
}

/// Save-rule version for the first world-scoped mutable spatial authority.
pub const CURRENT_SHARED_SPATIAL_RULES_VERSION: u32 = 1;

#[derive(Debug, Clone, PartialEq)]
pub struct SharedSpatialState {
    pub rules_version: u32,
    pub tiles: BTreeMap<TilePos, WorldTileRuntime>,
    pub fish_habitats: BTreeMap<TilePos, stockpiles::FishPopulation>,
}

impl Default for SharedSpatialState {
    fn default() -> Self {
        Self::current()
    }
}

impl SharedSpatialState {
    #[must_use]
    pub fn current() -> Self {
        Self {
            rules_version: CURRENT_SHARED_SPATIAL_RULES_VERSION,
            tiles: BTreeMap::new(),
            fish_habitats: BTreeMap::new(),
        }
    }
}

/// One barter proposal between villages that have met in the shared world.
/// Resources are checked when the receiving village accepts; an accepted offer
/// becomes a durable physical caravan and is removed from this open-offer book.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct VillageTradeOffer {
    pub id: String,
    pub from_colony_id: ColonyId,
    pub to_colony_id: ColonyId,
    pub offered_kind: ResourceKind,
    pub offered_amount: f64,
    pub requested_kind: ResourceKind,
    pub requested_amount: f64,
    pub created_at: i64,
}

/// The visible, persisted leg of an accepted inter-village barter.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum VillageTradeCaravanPhase {
    Outbound,
    WaitingAtTarget,
    Returning,
    WaitingAtSource,
}

/// A wire-friendly world coordinate for the explicit caravan actor.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct VillageTradePosition {
    pub x: f64,
    pub y: f64,
}

/// Exact source-pile debit captured when escrow is loaded.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct VillageTradeCargoSource {
    pub stockpile_id: String,
    pub amount: f64,
}

/// Durable escrow and physical progress for one accepted village trade.
///
/// Both finite scalar manifests are removed from their exact source stock at
/// acceptance. They therefore cannot be spent twice while the explicit actor is
/// on the road, and restart never needs to reconstruct a reservation from totals.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct VillageTradeCaravan {
    pub id: String,
    pub actor_id: String,
    pub from_colony_id: ColonyId,
    pub to_colony_id: ColonyId,
    pub offered_kind: ResourceKind,
    pub offered_amount: f64,
    pub requested_kind: ResourceKind,
    pub requested_amount: f64,
    pub offered_sources: Vec<VillageTradeCargoSource>,
    pub requested_sources: Vec<VillageTradeCargoSource>,
    /// Exact identity-bearing equipment removed from the source ledger while in
    /// transit. Scalar cargo leaves these manifests empty.
    #[serde(default)]
    pub offered_items: Vec<ItemInstance>,
    #[serde(default)]
    pub requested_items: Vec<ItemInstance>,
    /// Durable route geometry planned once from shared terrain and village gates.
    /// In-flight terrain changes never silently rewrite these waypoints.
    #[serde(default)]
    pub outbound_route: Vec<VillageTradePosition>,
    #[serde(default)]
    pub return_route: Vec<VillageTradePosition>,
    #[serde(default)]
    pub next_waypoint: usize,
    pub phase: VillageTradeCaravanPhase,
    pub position: VillageTradePosition,
    pub accepted_at: i64,
    pub last_advanced_at: i64,
}

#[derive(Debug, Clone, PartialEq)]
pub struct ColonyRuntime {
    pub id: ColonyId,
    pub name: String,
    pub kind: VillageKind,
    pub scale: VillageScale,
    /// Stable player identity controlling a personal village. `None` is valid
    /// for the global village and for quarantined legacy personal rows only.
    pub owner_player_id: Option<PlayerId>,
    /// Villages physically found by this colony's committed exploration. A
    /// contact is recorded mutually only after permanent shrine-delivered fog
    /// knowledge reaches the other village's shrine.
    pub known_village_ids: BTreeSet<ColonyId>,
    /// Open barter proposals authored by this village. Keeping offers on their
    /// source colony makes ownership and persistence explicit.
    pub village_trade_offers: BTreeMap<String, VillageTradeOffer>,
    /// Accepted trades whose finite escrow is physically crossing the shared map.
    pub village_trade_caravans: BTreeMap<String, VillageTradeCaravan>,
    pub leader_id: Option<CatId>,
    pub status: ColonyStatus,
    pub resources: Resources,
    pub cats: Vec<Cat>,
    pub jobs: Vec<JobRuntime>,
    pub buildings: Vec<BuildingRuntime>,
    pub events: Vec<EventLog>,
    pub world_tiles: BTreeMap<TilePos, WorldTileRuntime>,
    pub zones: Vec<ZoneRuntime>,
    pub elections: Vec<ElectionRuntime>,
    pub votes: Vec<VoteRuntime>,
    pub raiders: Vec<RaiderRuntime>,
    pub upgrade_levels: UpgradeLevels,
    pub upgrade_tree: UpgradeTreeState,
    /// Version 0 predates recipe entitlements and grandfathers every implemented
    /// station recipe. Fresh colonies use version 1 and must own the catalog study
    /// whose typed payload unlocks the recipe. Persisted queues are never rewritten.
    pub recipe_entitlement_rules_version: u32,
    /// Version 0 predates finite functional-equipment identity and may still carry
    /// whole Tools/Weapons/Armor only in scalar fields. Version 1 makes item units
    /// authoritative and keeps those fields as an ownership projection.
    pub finite_equipment_rules_version: u32,
    pub automation_tier: f64,
    pub global_upgrade_points: f64,
    pub ritual_requested_at: Option<i64>,
    pub critical_since: Option<i64>,
    pub claimed_tiles: Vec<TilePos>,
    /// Claimed exterior land reserved for farming rather than incorporated into the
    /// palisaded settlement. This is a subset of `claimed_tiles`: agricultural parcels
    /// remain owned, revealed, and workable, but never move the settlement wall or gate.
    pub agricultural_tiles: BTreeSet<TilePos>,
    /// World-tile coordinate of this colony's village anchor (the shrine footprint's NW
    /// corner). Colony 0 (the single founding colony) is always [`VILLAGE_ANCHOR`], so its
    /// every anchor-relative computation is byte-identical to the pre-multi-village code.
    /// A second village founded via `FoundVillage` gets a distinct anchor at a valid site
    /// far from every existing colony, and its whole spatial frame (blueprint, claimed
    /// tiles, roads, reveal, raids, movement conversions) is taken relative to *this*
    /// anchor rather than the global constant.
    pub anchor: TilePos,
    /// Permanently revealed fog-of-war tiles. The founding village seeds the claimed
    /// core plus a two-tile halo; later knowledge enters only when a returning scout
    /// reaches the shrine. This set is persisted independently of the lazily populated
    /// `world_tiles`, and its deterministic ordering is part of the snapshot contract.
    pub revealed_tiles: BTreeSet<TilePos>,
    /// Fog-of-war P15: tentative reveal for a scout currently out on an `Explore` job
    /// (and still on its way home) — keyed by scout cat id, holding the tiles that
    /// scout's walk has newly uncovered but not yet delivered. Committed into
    /// `revealed_tiles` when the scout reaches the shrine
    /// (`commit_scout_provisional_tiles`); dropped without committing if the scout
    /// dies before returning (`phase_25b_prune_dead_scout_provisional_tiles`).
    /// Persisted by the authoritative server so a restart cannot erase or commit an
    /// in-flight notebook. Legacy saves without it recreate an empty marker for each
    /// active/returning scout and resume provisional reveal safely.
    pub provisional_tiles: BTreeMap<CatId, BTreeSet<TilePos>>,
    /// Tiles delivered to the shrine by scouts during the current world tick.
    /// Discovery reconciliation consumes and clears this transient set at the end
    /// of the tick. Keeping provenance separate from `revealed_tiles` prevents
    /// expansion, recovery, or legacy map data from fabricating village contact.
    pub pending_scout_delivery_tiles: BTreeSet<TilePos>,
    /// Appointed officers (role → cat id). Vacant roles remain manual-only.
    pub officers: BTreeMap<OfficerRole, String>,
    /// On-map physical stores. Always includes the finite seeded general storehouse after
    /// a tick; ordinary piles plus station input/transit sum to `resources`.
    pub stockpiles: Vec<Stockpile>,
    /// Player-designated visible crop plots (P12.5). Empty for legacy colonies.
    pub farms: Vec<FarmPlot>,
    /// P16 gather spots: bookkeeping (resource kind + TTL) for whichever `stockpiles`
    /// entries are currently gather spots. Empty/inert for every colony that never
    /// designates one — the gatherer/mover split only activates once a spot exists.
    pub gather_spots: Vec<GatherSpot>,
    /// Finite shoreline ecology keyed by the canonical adjacent water tile.
    /// This survives removing/re-designating a fishing spot, so the player
    /// cannot refill a depleted habitat by repainting its bank.
    pub fish_habitats: BTreeMap<TilePos, stockpiles::FishPopulation>,
    /// Constructed P17 transport infrastructure, vehicles, and staffed routes.
    /// Research ownership is deliberately absent from this state: blueprints do
    /// not move a cat or a unit of cargo until this ledger says the work exists.
    pub transport: crate::transport::TransportState,
    /// Reported stock ledger (P12.4a). A lagging *view* of `resources`; only completed
    /// physical pile counts refresh it after the exact founding report. Never affects the
    /// true `resources`.
    pub stock_ledger: StockLedger,
    /// DF-scale finite item ledger (P19). Distinct `(kind, material, quality)` stacks
    /// retain stable per-unit identity and condition. Functional tool/weapon/armor
    /// counts mirror their physical `resources` piles; broken units remain present but
    /// do not contribute. Deterministic maps keep save and snapshot order stable.
    pub items: ItemStore,
    /// Woodworking bench's trade-craft cycle timer (P19 slice 2) — carries fractional
    /// progress toward [`crate::recipes::WOOD_TRADE_RECIPE`]'s cycle, entirely separate
    /// from `BuildingRuntime::production_progress` (which the bench's *functional*
    /// tools recipe still owns unchanged). Colony-level rather than per-building
    /// because exactly one Woodworking bench exists per founded colony.
    pub wood_craft_progress: f64,
    /// Frozen compatibility field from Stone Prep's removed hidden trade-craft timer.
    /// It remains serialized bit-for-bit for old saves but physical `stone_to_blocks`
    /// work advances only [`BuildingRuntime::production_progress`].
    pub stone_craft_progress: f64,
    /// Clothier bench's trade-craft cycle timer (P16/P19 clothing chain slice),
    /// mirroring [`Self::wood_craft_progress`] for [`crate::recipes::CLOTH_TRADE_RECIPE`].
    pub clothier_craft_progress: f64,
    /// Tannery bench's trade-craft cycle timer (P16/P19 clothing chain slice),
    /// mirroring [`Self::wood_craft_progress`] for [`crate::recipes::LEATHER_TRADE_RECIPE`].
    pub tannery_craft_progress: f64,
    /// Frozen compatibility field from Smithy's removed aggregate metal-forge timer.
    /// It remains serialized bit-for-bit for old saves; selected physical Smithy work
    /// advances only [`BuildingRuntime::production_progress`].
    pub metal_forge_progress: f64,
    /// Coin balance (P19 slice 3): earned by [`crate::trader::TraderState::Trading`]
    /// `SellGoods` and spent on `BuyResource`. Its own currency, deliberately not folded
    /// into `resources.blessings` or `global_upgrade_points` (the spec: "Do NOT overload
    /// blessings/upgrade points — coin is its own thing"). Like `global_upgrade_points`
    /// and `resources.blessings`, a colony reset (`reset_run`) does not zero this — it is
    /// banked player-facing wealth, not part of the survival-resource run state.
    pub coin: f64,
    /// The currently-visiting trader, if any (P19 slice 3) — `None` most of the time; a
    /// colony sees at most one trader at once. See [`crate::trader`] for the lifecycle/
    /// pricing model.
    pub trader: Option<TraderRuntime>,
    /// Monotonic manifest sequence. Incremented exactly once when a scheduled visit is
    /// created; persistence/restarts never reseed the current trader.
    pub trader_visit_count: u64,
    /// Tick timestamp (ms) the most recent trader visit ended (`TraderState::Departing`
    /// reaching the off-map spawn point and despawning). `None` before the colony's
    /// first-ever visit, in which case the schedule counts game-hours from
    /// `run_started_at` instead. Drives [`crate::trader::TRADER_VISIT_INTERVAL_GAME_HOURS`]'s
    /// threshold check — see `phase_36b_trader_lifecycle`.
    pub last_trader_departed_at: Option<i64>,
    /// Prosperity-migration cohort cursor and the physically present cats still waiting
    /// for a permanent bed. This is durable gameplay state, not a derived UI cache.
    pub migration_state: MigrationState,
    /// Lifetime count of probationary migrants who left this village without housing.
    pub migration_departures: u64,
    pub threat_pressure: f64,
    pub last_raid_at: Option<i64>,
    pub active_raid: Option<RaidId>,
    pub raid_clicks: f64,
    pub run_number: u32,
    pub run_started_at: i64,
    pub created_at: i64,
    pub last_player_activity_at: Option<i64>,
    /// Real-time timestamp of the Leader's most recent successful automatic
    /// research choice. Player-directed research is never rate-limited by this field.
    pub last_leader_research_choice_at: Option<i64>,
    /// Non-prunable cooldown anchors for shrine economy automation. Event logs are
    /// presentation history and may retain only the newest entries.
    pub last_tithe_at: Option<i64>,
    pub last_offering_at: Option<i64>,
    pub last_tick: i64,
    pub test_time_scale: f64,
    pub test_resource_decay_multiplier: f64,
    pub test_resilience_hours_override: Option<f64>,
    pub test_critical_ms_override: i64,
    pub test_rng_seed: Option<u32>,
    /// Runtime-only deterministic terrain cache (fine biomes plus decoration
    /// anchors). It is excluded from semantic equality and persistence; any
    /// loaded colony rebuilds identical entries from `(world_seed, chunk)` on
    /// first use.
    pub decoration_cache: DecorationCache,
}

#[derive(Debug, Clone, PartialEq)]
pub struct JobRuntime {
    pub id: JobId,
    pub kind: JobKind,
    pub status: JobStatus,
    pub requested_by: JobRequester,
    pub assigned_cat: Option<CatId>,
    pub duration_ms: i64,
    pub speed: f64,
    pub yield_amount: f64,
    pub click_count: u32,
    pub created_at: i64,
    pub started_at: Option<i64>,
    pub ends_at: Option<i64>,
    pub completed_at: Option<i64>,
    pub metadata: JobMetadata,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum JobRequester {
    Player,
    Leader,
    System,
}

#[derive(Debug, Clone, PartialEq)]
pub enum JobMetadata {
    None,
    Construction {
        phase: ConstructionPhase,
        building_type: BuildingType,
        building_id: Option<BuildingId>,
        site: Option<TilePos>,
    },
    /// One ordered authored-road project. Supplies remain reserved in exact visible
    /// source piles until the assigned builder picks up one unit for `tiles[next_tile]`.
    /// A tile becomes paved only after that cargo reaches the site and `work_ms`
    /// completes there.
    RoadConstruction {
        tiles: Vec<TilePos>,
        next_tile: usize,
        reservations: Vec<ConstructionCargoReservation>,
        work_ms: i64,
    },
    Expansion {
        target: TilePos,
        accepted: bool,
        /// Exact site-less construction whose builder was temporarily borrowed for
        /// this prerequisite expansion. `None` for ordinary crowding expansions.
        source_build_job_id: Option<JobId>,
        /// Durable hands-on wall work already completed. The prospective outer
        /// perimeter is deterministic from `(claimed area, target)`; persisting the
        /// elapsed work keeps partial segments stable across worker death and restart.
        wall_work_ms: i64,
    },
    Hauling {
        site: Option<TilePos>,
        total_yield: Option<f64>,
        trips_done: u32,
        next_trip_at: Option<i64>,
        accepted: bool,
    },
    Site {
        site: TilePos,
        accepted: bool,
    },
    /// A P16 gather-spot mover job: travel to the gather spot (`stockpile_id`), pick up
    /// its contents, and haul them to a village stockpile/shrine. `site` starts `None`
    /// (freshly queued) and is resolved to the gather spot's rect center by phase 15,
    /// exactly like [`Self::Hauling`]'s `site`. `accepted` flips once the assigned cat
    /// physically arrives (the generic accept-on-arrival mechanism shared with
    /// [`Self::Site`]/[`Self::Hauling`]) — the gather-spot pickup phase then completes
    /// the job.
    GatherHaul {
        stockpile_id: String,
        site: Option<TilePos>,
        accepted: bool,
    },
    /// A Steward-dispatched physical transfer between two visible stockpiles. Cargo
    /// moves through `transit_id`, a hidden persisted physical store, so rearranging
    /// existing goods never changes the colony aggregate while the cat is walking.
    StockpileHaul {
        source_stockpile_id: String,
        destination_stockpile_id: String,
        kind: ResourceKind,
        site: Option<TilePos>,
        accepted: bool,
        transit_id: String,
        amount_in_transit: f64,
    },
    /// Physical offering delivery. `source_stockpile_id` identifies the next
    /// visible pile to collect from; partial deliveries accumulate only in the persisted
    /// station-local `escrow_id` at the shrine. `delivered` mirrors that escrow for
    /// truthful phase inspection and deterministic restart recovery. Missing resource
    /// metadata in a legacy SQLite record migrates to Materials.
    OfferingCarry {
        source_stockpile_id: String,
        kind: ResourceKind,
        site: Option<TilePos>,
        accepted: bool,
        escrow_id: String,
        delivered: f64,
    },
    /// The second offering stage. The goods already exist in `escrow_id`; completion
    /// consumes exactly `amount` there before producing any blessing.
    OfferingRitual {
        escrow_id: String,
        kind: ResourceKind,
        amount: f64,
    },
    /// A scout excursion keeps its purpose and resolved route in durable job
    /// metadata. The per-cat provisional reveal remains transient, but this is
    /// enough to restore the scout marker after a server restart.
    Scout {
        mission: ScoutMission,
        /// A useful terrain feature only after it has entered this scout's
        /// provisional notebook. `None` while searching and after an unsuccessful
        /// bounded search; general exploration never sets it.
        target: Option<TilePos>,
        /// Current deterministic wander-leg endpoint. Route choice uses geometry
        /// and seeded movement rolls, never hidden resource values.
        destination: Option<TilePos>,
        accepted: bool,
        /// Set after the scout physically observes its target, finishes a general
        /// survey, or exhausts the bounded search and gives up.
        found: bool,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ScoutResource {
    Wood,
    Food,
    Water,
    Stone,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ScoutMission {
    Explore,
    Resource(ScoutResource),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConstructionPhase {
    GatherMaterials,
    ConstructHouse,
}

#[derive(Debug, Clone, PartialEq)]
pub struct BuildingRuntime {
    pub id: BuildingId,
    pub building_type: BuildingType,
    pub level: u32,
    pub position: TilePos,
    pub is_complete: bool,
    pub construction_progress: u8,
    pub production_progress: f64,
    pub assigned_cat: Option<CatId>,
    /// `Some(role)` only when the sim's officer automation made this assignment.
    /// Manual AssignWorker writes `None`, allowing vacancy reconciliation to stop
    /// sticky automated production without stripping a player's explicit worker.
    pub automated_by: Option<OfficerRole>,
    /// Additional researched worker stations. The legacy fields above remain slot zero
    /// so old saves and clients keep their exact shape; every added slot owns its worker,
    /// automation provenance, selected queue, pause state, and fractional work. Station
    /// input/output stores remain shared and finite, so slots contend in stable order
    /// instead of receiving hidden aggregate materials.
    pub additional_work_slots: Vec<ProductionWorkSlot>,
    /// Ordered, durable station instructions. Only recipe ids backed by a real
    /// implementation may enter this queue.
    pub production_queue: Vec<ProductionQueueEntry>,
    /// Pausing stops recipe work, but does not strand completed output at the station.
    pub production_paused: bool,
    /// Fresh scaffolds own an explicit finite material contract. `None` is the
    /// safe legacy shape: an incomplete scaffold persisted before physical
    /// construction logistics is grandfathered as already funded and is never
    /// charged a second time.
    pub construction_cargo: Option<ConstructionCargoState>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ProductionWorkSlot {
    pub assigned_cat: CatId,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub automated_by: Option<OfficerRole>,
    #[serde(default)]
    pub production_progress: f64,
    #[serde(default)]
    pub production_queue: Vec<ProductionQueueEntry>,
    #[serde(default)]
    pub production_paused: bool,
}

impl BuildingRuntime {
    #[must_use]
    pub fn has_worker(&self, cat_id: &str) -> bool {
        building_worker_ids(self).any(|assigned| assigned == cat_id)
    }

    #[must_use]
    pub fn worker_count(&self) -> usize {
        usize::from(self.assigned_cat.is_some())
            + self
                .additional_work_slots
                .iter()
                .filter(|slot| !slot.assigned_cat.is_empty())
                .count()
    }

    /// Remove one exact worker while preserving every remaining slot's owned work.
    /// If legacy slot zero is vacated, the oldest added slot is promoted atomically.
    pub fn remove_worker(&mut self, cat_id: &str) -> bool {
        if self.assigned_cat.as_deref() == Some(cat_id) {
            if let Some(index) = self
                .additional_work_slots
                .iter()
                .position(|slot| !slot.assigned_cat.is_empty())
            {
                let promoted = self.additional_work_slots.remove(index);
                let vacant = ProductionWorkSlot {
                    assigned_cat: String::new(),
                    automated_by: None,
                    production_progress: self.production_progress,
                    production_queue: std::mem::take(&mut self.production_queue),
                    production_paused: self.production_paused,
                };
                self.assigned_cat = Some(promoted.assigned_cat);
                self.automated_by = promoted.automated_by;
                self.production_progress = promoted.production_progress;
                self.production_queue = promoted.production_queue;
                self.production_paused = promoted.production_paused;
                self.additional_work_slots.insert(index, vacant);
            } else {
                self.assigned_cat = None;
                self.automated_by = None;
            }
            return true;
        }
        let Some(slot) = self
            .additional_work_slots
            .iter_mut()
            .find(|slot| slot.assigned_cat == cat_id)
        else {
            return false;
        };
        slot.assigned_cat.clear();
        slot.automated_by = None;
        true
    }

    pub fn add_worker(&mut self, cat_id: CatId, automated_by: Option<OfficerRole>) {
        if self.assigned_cat.is_none() {
            self.assigned_cat = Some(cat_id);
            self.automated_by = automated_by;
            return;
        }
        if let Some(slot) = self
            .additional_work_slots
            .iter_mut()
            .find(|slot| slot.assigned_cat.is_empty())
        {
            slot.assigned_cat = cat_id;
            slot.automated_by = automated_by;
            return;
        }
        self.additional_work_slots.push(ProductionWorkSlot {
            assigned_cat: cat_id,
            automated_by,
            production_progress: 0.0,
            production_queue: default_production_queue(self.building_type),
            production_paused: false,
        });
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ConstructionCargoReservation {
    pub source_stockpile_id: String,
    pub kind: ResourceKind,
    pub amount: f64,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub struct ConstructionCargoState {
    pub required_lumber: f64,
    pub required_planks: f64,
    pub required_blocks: f64,
    pub delivered_lumber: f64,
    pub delivered_planks: f64,
    pub delivered_blocks: f64,
    #[serde(default)]
    pub reservations: Vec<ConstructionCargoReservation>,
    #[serde(default)]
    pub consumed: bool,
}

impl ConstructionCargoState {
    #[must_use]
    pub fn required_timber(&self) -> f64 {
        self.required_lumber + self.required_planks
    }

    #[must_use]
    pub fn delivered_timber(&self) -> f64 {
        self.delivered_lumber + self.delivered_planks
    }

    #[must_use]
    pub fn is_delivered(&self) -> bool {
        self.delivered_lumber + f64::EPSILON >= self.required_lumber
            && self.delivered_planks + f64::EPSILON >= self.required_planks
            && self.delivered_blocks + f64::EPSILON >= self.required_blocks
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProductionQueueEntry {
    pub recipe_id: String,
    pub repeat: bool,
}

/// Fresh-colony ruleset: researched recipes require their catalog study while
/// descriptor-marked founding baseline recipes remain immediately usable.
pub const CURRENT_RECIPE_ENTITLEMENT_RULES_VERSION: u32 = 1;
/// Fresh-colony functional equipment uses stable item identities as the sole
/// condition/location authority. Scalar fields remain a derived ownership view.
pub const CURRENT_FINITE_EQUIPMENT_RULES_VERSION: u32 = 1;

/// Stable recipe ids implemented by each authoritative station. Entitlement is
/// colony-specific and must be checked through [`production_recipe_availability`].
#[must_use]
pub fn available_production_recipes(building_type: BuildingType) -> Vec<&'static str> {
    crate::station_recipes::station_recipe_set(building_type).map_or_else(Vec::new, |station| {
        station.recipes.iter().map(|recipe| recipe.id).collect()
    })
}

/// Catalog-backed entitlement for one implemented station recipe.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ProductionRecipeAvailability {
    /// The exact stable recipe ID owned by this station's descriptor.
    pub recipe_id: &'static str,
    /// Study whose typed payload unlocks the recipe, if the catalog owns one.
    pub required_study_id: Option<&'static str>,
    /// Whether this colony may advance or newly queue this recipe.
    pub available: bool,
}

/// Catalog entitlement shared by editable descriptor queues and the compatibility
/// aggregate production paths that still execute until each physical route lands.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CatalogRecipeEntitlement {
    pub required_study_id: Option<&'static str>,
    pub available: bool,
}

/// Resolve a maintained station recipe directly from the catalog reverse index.
/// Rules-v0 colonies are grandfathered exactly as the queue stations are; fresh
/// rules-v1 colonies require the study carrying that exact recipe payload.
#[must_use]
pub fn catalog_recipe_entitlement(
    colony: &ColonyRuntime,
    recipe_id: &str,
) -> CatalogRecipeEntitlement {
    let required_study_id = research_catalog()
        .recipe_unlock_study(recipe_id)
        .map(|node| node.id.as_str());
    let available = colony.recipe_entitlement_rules_version == 0
        || required_study_id.is_some_and(|study| is_owned(&colony.upgrade_tree, study));
    CatalogRecipeEntitlement {
        required_study_id,
        available,
    }
}

/// Resolve the one authoritative recipe entitlement view used by snapshots,
/// signed queue edits, block reasons, and physical production. Requirement
/// ownership comes from catalog payload data, never a parallel recipe→study map.
#[must_use]
pub fn production_recipe_availability(
    colony: &ColonyRuntime,
    building_type: BuildingType,
    recipe_id: &str,
) -> Option<ProductionRecipeAvailability> {
    let recipe = crate::station_recipes::station_recipe_set(building_type)?
        .recipes
        .iter()
        .find(|implemented| implemented.id == recipe_id)?;
    let recipe_id = recipe.id;
    let entitlement = catalog_recipe_entitlement(colony, recipe_id);
    Some(ProductionRecipeAvailability {
        recipe_id,
        required_study_id: entitlement.required_study_id,
        available: recipe.founding_available || entitlement.available,
    })
}

#[must_use]
pub fn default_production_queue(building_type: BuildingType) -> Vec<ProductionQueueEntry> {
    crate::station_recipes::station_recipe_set(building_type).map_or_else(Vec::new, |station| {
        station
            .recipes
            .iter()
            // Material variants are deliberate player/research additions, not
            // surprise defaults that could strand a founding survival queue on
            // its first still-locked study.
            .filter(|recipe| {
                recipe.output_item.is_none()
                    && food_plant_physical_recipe(recipe.id).is_none()
                    && industrial_physical_recipe(recipe.id).is_none()
            })
            .map(|recipe| ProductionQueueEntry {
                recipe_id: recipe.id.to_owned(),
                repeat: true,
            })
            .collect()
    })
}

/// Replace the old implicit two-stage Mill operation in persisted queues with
/// two explicit physical operations. Entry order and repeat intent are stable,
/// and rerunning the migration is a no-op.
pub fn migrate_split_mill_queues(colony: &mut ColonyRuntime) {
    for building in colony
        .buildings
        .iter_mut()
        .filter(|building| building.building_type == BuildingType::Mill)
    {
        let mut migrated = Vec::with_capacity(building.production_queue.len() + 1);
        for entry in building.production_queue.drain(..) {
            if entry.recipe_id == crate::station_recipes::LEGACY_COMBINED_MILL_RECIPE_ID {
                migrated.push(ProductionQueueEntry {
                    recipe_id: crate::station_recipes::GRAIN_TO_FLOUR_RECIPE_ID.to_owned(),
                    repeat: entry.repeat,
                });
                migrated.push(ProductionQueueEntry {
                    recipe_id: crate::station_recipes::FLOUR_TO_FOOD_RECIPE_ID.to_owned(),
                    repeat: entry.repeat,
                });
            } else {
                migrated.push(entry);
            }
        }
        building.production_queue = migrated;
    }
}

/// Add the newly explicit spinning step immediately before legacy weaving
/// entries. Intentionally empty queues stay empty, authored order/repeat flags
/// stay intact, and rerunning the migration is a no-op.
pub fn migrate_split_clothier_queues(colony: &mut ColonyRuntime) {
    let thread_in_flight = colony.resources.thread > f64::EPSILON
        || colony
            .stockpiles
            .iter()
            .any(|pile| pile.contents.thread > f64::EPSILON)
        || colony.cats.iter().any(|cat| {
            cat.carrying
                .as_ref()
                .is_some_and(|cargo| cargo.kind == CarryingKind::Thread)
        });
    fn migrate(queue: &mut Vec<ProductionQueueEntry>, thread_in_flight: bool) {
        if queue.is_empty()
            || thread_in_flight
            || queue
                .iter()
                .any(|entry| entry.recipe_id == CLOTHIER_THREAD_RECIPE_ID)
        {
            return;
        }
        let Some(index) = queue
            .iter()
            .position(|entry| entry.recipe_id == CLOTHIER_RECIPE_ID)
        else {
            return;
        };
        let repeat = queue[index].repeat;
        queue.insert(
            index,
            ProductionQueueEntry {
                recipe_id: CLOTHIER_THREAD_RECIPE_ID.to_owned(),
                repeat,
            },
        );
    }

    for building in colony
        .buildings
        .iter_mut()
        .filter(|building| building.building_type == BuildingType::Clothier)
    {
        migrate(&mut building.production_queue, thread_in_flight);
        for slot in &mut building.additional_work_slots {
            migrate(&mut slot.production_queue, thread_in_flight);
        }
    }
}

/// Tile footprint `(width, height)` a building of `building_type` occupies.
///
/// The footprint is a pure function of the building type — it is *derived*, never
/// persisted, so a building still stores only `position + type`. `position` is the
/// footprint's **anchor = its minimum (north-west) corner**; the building covers the
/// half-open rectangle `[x, x + w) x [y, y + h)` (see [`footprint_tiles`]).
#[must_use]
pub const fn footprint_for(building_type: BuildingType) -> (i32, i32) {
    match building_type {
        // The shrine is the village hub, and the workshops/storehouse are broad
        // work-yards — all 3x3 (P16).
        BuildingType::Shrine
        | BuildingType::Workshop
        | BuildingType::Smithy
        | BuildingType::FoodStorage
        | BuildingType::WoodCutter
        | BuildingType::StonePrep
        | BuildingType::Woodworking
        | BuildingType::Clothier
        | BuildingType::Tannery
        | BuildingType::Smelter
        | BuildingType::Mill
        | BuildingType::Sawmill => (3, 3),
        // Dwellings, gardens and the mid buildings take a 2x3 plot (P16).
        BuildingType::Den
        | BuildingType::Beds
        | BuildingType::Nursery
        | BuildingType::HerbGarden
        | BuildingType::ElderCorner
        | BuildingType::MouseFarm
        | BuildingType::Field
        | BuildingType::Barracks
        | BuildingType::ResearchHut
        | BuildingType::School
        | BuildingType::AccountingTent => (2, 3),
        // Bowls and wall segments are single tiles.
        BuildingType::WaterBowl | BuildingType::Walls => (1, 1),
    }
}

/// The tiles covered by a `w x h` footprint anchored at its north-west corner
/// `position` — i.e. `[x, x + w) x [y, y + h)`, row-major. Empty if `w`/`h` <= 0.
#[must_use]
pub fn footprint_tiles(position: TilePos, w: i32, h: i32) -> Vec<TilePos> {
    let mut tiles = Vec::with_capacity((w.max(0) * h.max(0)) as usize);
    for dy in 0..h {
        for dx in 0..w {
            tiles.push(TilePos {
                x: position.x + dx,
                y: position.y + dy,
            });
        }
    }
    tiles
}

/// Tiles covered by an existing building's derived footprint.
fn building_footprint_tiles(building: &BuildingRuntime) -> Vec<TilePos> {
    let (w, h) = footprint_for(building.building_type);
    footprint_tiles(building.position, w, h)
}

/// Every tile currently covered by any building's footprint.
fn occupied_building_tiles(colony: &ColonyRuntime) -> HashSet<TilePos> {
    colony
        .buildings
        .iter()
        .flat_map(building_footprint_tiles)
        .collect()
}

/// Why a new spatial footprint cannot be committed. Existing persisted rows are
/// deliberately not retroactively rejected; this enum is only consulted at new
/// mutation boundaries (building break-ground and stockpile designation).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SpatialPlacementError {
    InvalidRectangle,
    UnmappedTerrain,
    OutsideClaim,
    Building,
    Stockpile,
    Farm,
    Water,
    Tree,
    Rock,
    Mountain,
    PerimeterWall,
    Road,
}

impl SpatialPlacementError {
    /// Stable player-facing explanation for rejected placement actions.
    #[must_use]
    pub const fn message(self) -> &'static str {
        match self {
            Self::InvalidRectangle => "The placement rectangle is invalid.",
            Self::UnmappedTerrain => "The placement must lie on mapped, revealed terrain.",
            Self::OutsideClaim => "The placement must lie entirely on claimed village land.",
            Self::Building => "The placement overlaps a building footprint.",
            Self::Stockpile => "The placement overlaps another stockpile.",
            Self::Farm => "The placement overlaps a designated farm.",
            Self::Water => "The placement overlaps water.",
            Self::Tree => "The placement overlaps a tree.",
            Self::Rock => "The placement overlaps a rock.",
            Self::Mountain => "The placement overlaps impassable mountain terrain.",
            Self::PerimeterWall => "The placement overlaps the village perimeter wall.",
            Self::Road => "The placement overlaps a paved road.",
        }
    }
}

fn tile_has_paved_road(colony: &ColonyRuntime, tile: TilePos) -> bool {
    colony
        .world_tiles
        .get(&tile)
        .is_some_and(|tile| tile.overlay_feature.as_deref() == Some("road_built"))
}

fn runtime_decoration_cleared(tile: &WorldTileRuntime) -> bool {
    matches!(tile.overlay_feature.as_deref(), Some("stump" | "sapling"))
        || (tile.last_depleted > 0
            && (tile.tile_type == TileType::Field
                || (tile.tile_type == TileType::Meadow
                    && tile.resources.food == 0
                    && tile.resources.herbs == 0
                    && tile.resources.water == 0
                    && tile.max_resources.food == 0
                    && tile.max_resources.herbs == 0)))
}

/// Deterministic tree decorations are physical blockers until a forest tile is
/// explicitly cleared. Expansion records that clearing as `TileType::Field`;
/// merely belonging to the founding claim does not erase a tree decoration.
#[cfg(test)]
fn tile_has_uncleared_tree(colony: &ColonyRuntime, tile: TilePos, world_seed: u32) -> bool {
    !tile_coordinates_supported(tile)
        || (!inside_village_interior(colony, tile)
            && !colony
                .world_tiles
                .get(&tile)
                .is_some_and(runtime_decoration_cleared)
            && ((tile.y - (crate::terrain_gen::TREE_FOOTPRINT_HEIGHT - 1))..=tile.y).any(
                |anchor_y| {
                    ((tile.x - (crate::terrain_gen::TREE_FOOTPRINT_WIDTH - 1))..=tile.x).any(
                        |anchor_x| {
                            crate::terrain_gen::tile_has_tree(world_seed, anchor_x, anchor_y)
                        },
                    )
                },
            ))
}

#[derive(Debug, Clone, Default, PartialEq)]
struct DecorationAnchors {
    trees: HashSet<TilePos>,
    rocks: HashSet<TilePos>,
    climate_biomes: BTreeMap<TilePos, crate::climate::Biome>,
}

type ConstructionRoadRouteKey = (u64, i32, i32, String);
type ConstructionRoadRouteCache = BTreeMap<ConstructionRoadRouteKey, Option<Vec<TilePos>>>;

#[derive(Debug, Clone, Default)]
pub struct DecorationCache {
    chunks: BTreeMap<(u32, i32, i32), DecorationAnchors>,
    /// Failed Farmer auto-designations keyed by Field id and the authoritative rural
    /// geometry signature they searched. This derived cache prevents a land-starved
    /// Field from rebuilding occupancy indexes every tick; claim/reveal/farm/building
    /// changes deterministically re-arm it. A loaded game may retry once after restart.
    farm_designation_failures: BTreeMap<String, u64>,
    farm_route_component: RefCell<Option<(u64, HashSet<PathTilePos>)>>,
    /// Shared physical-accounting connectivity, keyed by authoritative topology. A round
    /// asks for this once and then persists its deterministic target queue.
    accounting_route_component: RefCell<Option<(u64, HashSet<PathTilePos>)>>,
    /// Derived reachability for Steward source/destination pairs. Resource quantities do
    /// not affect the key, so an unreachable route is not recomputed every decision tick.
    steward_route_reachability: RefCell<BTreeMap<u64, bool>>,
    /// Derived access routes for queued construction reservations. A funded project can
    /// wait many ticks for a manual road; unchanged village geometry must not rerun the
    /// same footprint-to-shrine path search in both phases 14 and 32 every second.
    construction_road_routes: RefCell<ConstructionRoadRouteCache>,
    #[cfg(test)]
    farm_route_debug: FarmRouteDebug,
    #[cfg(test)]
    farm_route_component_traversals: std::cell::Cell<u64>,
    #[cfg(test)]
    farm_route_component_cache_hits: std::cell::Cell<u64>,
    #[cfg(test)]
    farm_route_queries: std::cell::Cell<u64>,
    #[cfg(test)]
    water_route_queries: std::cell::Cell<u64>,
    #[cfg(test)]
    construction_route_queries: std::cell::Cell<u64>,
    #[cfg(test)]
    accounting_route_component_traversals: std::cell::Cell<u64>,
    #[cfg(test)]
    accounting_route_component_cache_hits: std::cell::Cell<u64>,
}

#[cfg(test)]
#[derive(Debug, Clone, Default)]
struct FarmRouteDebug {
    designation_searches: u64,
    designation_candidates: u64,
    designation_gather_failures: u64,
    designation_route_failures: u64,
    movement_ticks: u64,
    route_misses: u64,
    consecutive_traveling: BTreeMap<String, u64>,
    max_consecutive_traveling: u64,
    completed_short_haul_routes: u64,
    first_designated_at: Option<i64>,
    active_work_seconds: f64,
    at_plot_work_ticks: u64,
    unique_worker_ids: BTreeSet<String>,
    max_plots_per_worker: usize,
    emergency_worker_preemptions: u64,
    worker_releases: u64,
    effective_growth_by_plot: BTreeMap<String, f64>,
    harvests_by_plot: BTreeMap<String, u64>,
}

#[cfg(test)]
impl FarmRouteDebug {
    fn record_movement_pass(&mut self, cat_id: &str, route_found: bool) {
        self.movement_ticks += 1;
        if !route_found {
            self.route_misses += 1;
        }
        let consecutive = self
            .consecutive_traveling
            .entry(cat_id.to_owned())
            .and_modify(|ticks| *ticks += 1)
            .or_insert(1);
        self.max_consecutive_traveling = self.max_consecutive_traveling.max(*consecutive);
    }

    fn finish_movement_leg(&mut self, cat_id: &str) {
        self.consecutive_traveling.remove(cat_id);
    }
}

// A cache never changes authoritative simulation meaning. Treating two cache
// populations as equal keeps determinism/persistence assertions about gameplay
// state independent from which read-only route happened to warm a chunk first.
impl PartialEq for DecorationCache {
    fn eq(&self, _other: &Self) -> bool {
        true
    }
}

impl DecorationCache {
    /// Returns whether this derived cache has not generated any terrain chunks yet.
    /// Persisted colonies always load in this state and lazily rebuild entries.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.chunks.is_empty()
    }

    fn ensure_chunks(&mut self, world_seed: u32, chunks: &BTreeSet<(i32, i32)>) {
        let missing = chunks
            .iter()
            .copied()
            .filter(|&(chunk_x, chunk_y)| {
                !self.chunks.contains_key(&(world_seed, chunk_x, chunk_y))
            })
            .collect::<BTreeSet<_>>();
        for ((chunk_x, chunk_y), anchors) in decoration_anchors_for_chunks(world_seed, &missing) {
            self.chunks.insert((world_seed, chunk_x, chunk_y), anchors);
        }
    }

    fn anchors(&self, world_seed: u32, chunk_x: i32, chunk_y: i32) -> Option<&DecorationAnchors> {
        self.chunks.get(&(world_seed, chunk_x, chunk_y))
    }

    fn climate_biome(&self, world_seed: u32, pos: TilePos) -> Option<crate::climate::Biome> {
        let chunk_x = pos.x.div_euclid(crate::terrain_gen::TERRAIN_CHUNK_SIZE);
        let chunk_y = pos.y.div_euclid(crate::terrain_gen::TERRAIN_CHUNK_SIZE);
        self.anchors(world_seed, chunk_x, chunk_y)
            .and_then(|chunk| chunk.climate_biomes.get(&pos).copied())
    }
}

fn decoration_anchors_for_chunk(world_seed: u32, chunk_x: i32, chunk_y: i32) -> DecorationAnchors {
    decoration_anchors_for_chunks(world_seed, &BTreeSet::from([(chunk_x, chunk_y)]))
        .remove(&(chunk_x, chunk_y))
        .expect("requested decoration chunk is always generated")
}

fn decoration_anchors_for_chunks(
    world_seed: u32,
    chunks: &BTreeSet<(i32, i32)>,
) -> BTreeMap<(i32, i32), DecorationAnchors> {
    let mut out = chunks
        .iter()
        .map(|&chunk| (chunk, DecorationAnchors::default()))
        .collect::<BTreeMap<_, _>>();
    for &(chunk_x, chunk_y) in chunks {
        let anchors = out
            .get_mut(&(chunk_x, chunk_y))
            .expect("requested chunk was initialized");
        for terrain in crate::terrain_gen::generate_terrain_chunk(
            chunk_x,
            chunk_y,
            i64::from(world_seed),
            crate::terrain_gen::WORLD_TERRAIN_OPTIONS,
        ) {
            anchors.climate_biomes.insert(
                TilePos {
                    x: terrain.x,
                    y: terrain.y,
                },
                terrain.climate_biome,
            );
        }
    }
    for ((x, y), decoration) in
        crate::terrain_gen::resolved_biome_decorations_for_chunks(i64::from(world_seed), chunks)
    {
        let chunk = (
            x.div_euclid(crate::terrain_gen::TERRAIN_CHUNK_SIZE),
            y.div_euclid(crate::terrain_gen::TERRAIN_CHUNK_SIZE),
        );
        let anchors = out
            .get_mut(&chunk)
            .expect("resolver returns only requested decoration anchors");
        match decoration {
            crate::terrain_gen::DecorationRole::Tree { .. } => {
                anchors.trees.insert(TilePos { x, y });
            }
            crate::terrain_gen::DecorationRole::Rock { .. } => {
                anchors.rocks.insert(TilePos { x, y });
            }
        }
    }
    out
}

/// Immutable spatial indexes shared by one placement/access-route search.
///
/// A route may inspect thousands of tiles. Rebuilding the claimed/building sets and
/// regenerating a complete 12x12 terrain chunk for every inspected tile made a single
/// crowded-colony placement take seconds. This context preserves the exact predicates
/// while building the static indexes once and lazily generating each terrain chunk once.
struct SpatialOccupancyContext {
    world_seed: u32,
    claimed: HashSet<TilePos>,
    walled_claimed: HashSet<TilePos>,
    building_tiles: HashSet<TilePos>,
    stockpile_rects: Vec<ZoneRect>,
    road_blocking_stockpile_rects: Vec<ZoneRect>,
    farm_rects: Vec<ZoneRect>,
    water_tiles: HashSet<TilePos>,
    cleared_tree_tiles: HashSet<TilePos>,
    growing_tree_tiles: HashSet<TilePos>,
    mountain_tiles: HashSet<TilePos>,
    prepared_farm_tiles: HashSet<TilePos>,
    paved_road_tiles: HashSet<TilePos>,
    reserved_road_tiles: HashSet<TilePos>,
    mapped_tiles: HashSet<TilePos>,
    shrine_tiles: HashSet<TilePos>,
    gate: Option<TilePos>,
    decoration_chunks: RefCell<BTreeMap<(i32, i32), DecorationAnchors>>,
    farm_fertility_chunks: RefCell<BTreeMap<(i32, i32), HashMap<TilePos, f64>>>,
}

impl SpatialOccupancyContext {
    fn new(colony: &ColonyRuntime, world_seed: u32) -> Self {
        let claimed: HashSet<TilePos> = colony.claimed_tiles.iter().copied().collect();
        let walled_claimed = claimed
            .iter()
            .copied()
            .filter(|tile| !colony.agricultural_tiles.contains(tile))
            .collect();
        let building_tiles = occupied_building_tiles(colony);
        let stockpile_rects = colony
            .stockpiles
            .iter()
            // Station-local stores are inventories attached to an existing building or
            // in-flight route, not independently placeable map footprints. Treating the
            // transit ledger as a second pile at the general store could sever the only
            // gate-to-shrine road during expansion.
            .filter(|pile| !pile.is_shrine() && !pile.is_station_local())
            .map(|pile| pile.rect)
            .collect::<Vec<_>>();
        // Steward-managed piles are floor zones rather than hard map furniture. They
        // continue to reserve their tile from buildings, farms, and other stockpiles,
        // but a road designation may cross one without severing an otherwise unique
        // shrine-to-gate corridor. Ordinary player piles keep their stricter collision
        // rule, so automation never changes the meaning of a player-authored zone.
        let road_blocking_stockpile_rects = colony
            .stockpiles
            .iter()
            .filter(|pile| {
                !pile.is_shrine()
                    && !pile.is_station_local()
                    && !colony
                        .stock_ledger
                        .steward_managed_piles
                        .contains_key(&pile.id)
            })
            .map(|pile| pile.rect)
            .collect();
        let farm_rects = colony.farms.iter().map(|farm| farm.rect).collect();
        let water_tiles = colony
            .world_tiles
            .iter()
            .filter_map(|(&pos, tile)| tile_has_water(Some(tile)).then_some(pos))
            .collect();
        let cleared_tree_tiles = colony
            .world_tiles
            .iter()
            .filter_map(|(&pos, tile)| {
                (runtime_decoration_cleared(tile) || inside_village_interior(colony, pos))
                    .then_some(pos)
            })
            .collect();
        let growing_tree_tiles = colony
            .world_tiles
            .iter()
            .filter_map(|(&pos, tile)| {
                (tile.overlay_feature.as_deref() == Some("sapling")).then_some(pos)
            })
            .flat_map(tree_footprint_tiles)
            .collect();
        let mountain_tiles = if resolve_effects(colony.upgrade_tree.owned_node_ids.iter())
            .unlocked_capabilities
            .contains("mountain_travel")
        {
            HashSet::new()
        } else {
            colony
                .world_tiles
                .iter()
                .filter_map(|(&pos, tile)| (tile.tile_type == TileType::Mountains).then_some(pos))
                .collect()
        };
        let prepared_farm_tiles = colony
            .world_tiles
            .iter()
            .filter_map(|(&pos, tile)| {
                matches!(
                    tile.tile_type,
                    TileType::Field | TileType::Meadow | TileType::Swamp
                )
                .then_some(pos)
            })
            .collect();
        let paved_road_tiles = colony
            .world_tiles
            .iter()
            .filter_map(|(&pos, tile)| {
                (tile.overlay_feature.as_deref() == Some("road_built")).then_some(pos)
            })
            .collect();
        let reserved_road_tiles = colony
            .jobs
            .iter()
            .filter(|job| matches!(job.status, JobStatus::Queued | JobStatus::Active))
            .filter_map(|job| match &job.metadata {
                JobMetadata::RoadConstruction {
                    tiles, next_tile, ..
                } => Some(&tiles[(*next_tile).min(tiles.len())..]),
                _ => None,
            })
            .flatten()
            .copied()
            .collect();
        let mapped_tiles = colony.world_tiles.keys().copied().collect();
        let shrine_tiles = shrine_footprint_tiles(colony);
        let gate = retained_area_gate(colony).map(|gate| TilePos {
            x: gate.x,
            y: gate.y,
        });
        let decoration_chunks = colony
            .decoration_cache
            .chunks
            .iter()
            .filter_map(|(&(seed, chunk_x, chunk_y), anchors)| {
                (seed == world_seed).then_some(((chunk_x, chunk_y), anchors.clone()))
            })
            .collect();

        Self {
            world_seed,
            claimed,
            walled_claimed,
            building_tiles,
            stockpile_rects,
            road_blocking_stockpile_rects,
            farm_rects,
            water_tiles,
            cleared_tree_tiles,
            growing_tree_tiles,
            mountain_tiles,
            prepared_farm_tiles,
            paved_road_tiles,
            reserved_road_tiles,
            mapped_tiles,
            shrine_tiles,
            gate,
            decoration_chunks: RefCell::new(decoration_chunks),
            farm_fertility_chunks: RefCell::new(BTreeMap::new()),
        }
    }

    fn farm_fertility(&self, tile: TilePos) -> f64 {
        if !self.mapped_tiles.contains(&tile) || self.water_tiles.contains(&tile) {
            return 0.0;
        }
        let chunk = tile_to_chunk(tile.x, tile.y);
        let key = (chunk.chunk_x, chunk.chunk_y);
        let mut chunks = self.farm_fertility_chunks.borrow_mut();
        let fertility = chunks.entry(key).or_insert_with(|| {
            crate::terrain_gen::generate_terrain_chunk(
                chunk.chunk_x,
                chunk.chunk_y,
                i64::from(self.world_seed),
                crate::terrain_gen::WORLD_TERRAIN_OPTIONS,
            )
            .into_iter()
            .map(|generated| {
                (
                    TilePos {
                        x: generated.x,
                        y: generated.y,
                    },
                    generated.climate_biome.properties().fertility,
                )
            })
            .collect()
        });
        effective_farm_fertility(
            true,
            false,
            self.prepared_farm_tiles.contains(&tile),
            fertility.get(&tile).copied().unwrap_or_default(),
        )
    }

    fn farmable_ground(&self, tile: TilePos) -> bool {
        self.mapped_tiles.contains(&tile)
            && !self.water_tiles.contains(&tile)
            && (self.prepared_farm_tiles.contains(&tile) || self.farm_fertility(tile) > 0.0)
    }

    fn farm_rect_touches_claim_boundary(&self, rect: ZoneRect) -> bool {
        farming::rect_tiles(rect).any(|tile| {
            [(0, -1), (1, 0), (0, 1), (-1, 0)]
                .into_iter()
                .any(|(dx, dy)| {
                    !self.claimed.contains(&TilePos {
                        x: tile.x + dx,
                        y: tile.y + dy,
                    })
                })
        })
    }

    fn has_stockpile(&self, tile: TilePos) -> bool {
        self.stockpile_rects
            .iter()
            .any(|&rect| stockpiles::rect_contains(rect, tile.x, tile.y))
    }

    fn has_road_blocking_stockpile(&self, tile: TilePos) -> bool {
        self.road_blocking_stockpile_rects
            .iter()
            .any(|&rect| stockpiles::rect_contains(rect, tile.x, tile.y))
    }

    fn has_farm(&self, tile: TilePos) -> bool {
        self.farm_rects
            .iter()
            .any(|&rect| stockpiles::rect_contains(rect, tile.x, tile.y))
    }

    fn has_uncleared_tree(&self, tile: TilePos) -> bool {
        if !self.mapped_tiles.contains(&tile) || self.cleared_tree_tiles.contains(&tile) {
            return false;
        }
        ((tile.y - (crate::terrain_gen::TREE_FOOTPRINT_HEIGHT - 1))..=tile.y).any(|anchor_y| {
            ((tile.x - (crate::terrain_gen::TREE_FOOTPRINT_WIDTH - 1))..=tile.x)
                .any(|anchor_x| self.decoration_at(anchor_x, anchor_y, true))
        })
    }

    fn has_uncleared_rock(&self, tile: TilePos) -> bool {
        self.mapped_tiles.contains(&tile)
            && !self.cleared_tree_tiles.contains(&tile)
            && self.decoration_at(tile.x, tile.y, false)
    }

    fn decoration_at(&self, x: i32, y: i32, tree: bool) -> bool {
        let chunk = (
            x.div_euclid(crate::terrain_gen::TERRAIN_CHUNK_SIZE),
            y.div_euclid(crate::terrain_gen::TERRAIN_CHUNK_SIZE),
        );
        let mut chunks = self.decoration_chunks.borrow_mut();
        let anchors = chunks
            .entry(chunk)
            .or_insert_with(|| decoration_anchors_for_chunk(self.world_seed, chunk.0, chunk.1));
        let pos = TilePos { x, y };
        if tree {
            anchors.trees.contains(&pos)
        } else {
            anchors.rocks.contains(&pos)
        }
    }

    fn is_perimeter(&self, tile: TilePos) -> bool {
        tile_is_on_fence_perimeter(&self.walled_claimed, tile)
    }

    fn tile_is_occupied(&self, tile: TilePos) -> bool {
        !tile_coordinates_supported(tile)
            || !self.mapped_tiles.contains(&tile)
            || self.building_tiles.contains(&tile)
            || self.has_stockpile(tile)
            || self.has_farm(tile)
            || self.water_tiles.contains(&tile)
            || self.growing_tree_tiles.contains(&tile)
            || self.has_uncleared_tree(tile)
            || self.has_uncleared_rock(tile)
            || self.mountain_tiles.contains(&tile)
            || self.is_perimeter(tile)
            || self.paved_road_tiles.contains(&tile)
            || self.reserved_road_tiles.contains(&tile)
    }

    fn farm_tile_is_occupied(&self, tile: TilePos) -> bool {
        !tile_coordinates_supported(tile)
            || !self.mapped_tiles.contains(&tile)
            || self.building_tiles.contains(&tile)
            || self.has_stockpile(tile)
            || self.has_farm(tile)
            || self.water_tiles.contains(&tile)
            || self.growing_tree_tiles.contains(&tile)
            || self.has_uncleared_tree(tile)
            || self.has_uncleared_rock(tile)
            || self.mountain_tiles.contains(&tile)
            // A boundary-connected farm deliberately replaces this wall segment.
            || self.paved_road_tiles.contains(&tile)
            || self.reserved_road_tiles.contains(&tile)
    }

    fn placement_error_for_tiles(
        &self,
        tiles: &[TilePos],
        require_claimed: bool,
    ) -> Option<SpatialPlacementError> {
        if require_claimed && tiles.iter().any(|tile| !self.claimed.contains(tile)) {
            return Some(SpatialPlacementError::OutsideClaim);
        }
        if tiles
            .iter()
            .any(|tile| !tile_coordinates_supported(*tile) || !self.mapped_tiles.contains(tile))
        {
            return Some(SpatialPlacementError::UnmappedTerrain);
        }
        if tiles.iter().any(|tile| self.building_tiles.contains(tile)) {
            return Some(SpatialPlacementError::Building);
        }
        if tiles.iter().any(|&tile| self.has_stockpile(tile)) {
            return Some(SpatialPlacementError::Stockpile);
        }
        if tiles.iter().any(|&tile| self.has_farm(tile)) {
            return Some(SpatialPlacementError::Farm);
        }
        if tiles.iter().any(|tile| self.water_tiles.contains(tile)) {
            return Some(SpatialPlacementError::Water);
        }
        if tiles
            .iter()
            .any(|tile| self.growing_tree_tiles.contains(tile))
        {
            return Some(SpatialPlacementError::Tree);
        }
        if tiles.iter().any(|&tile| self.has_uncleared_tree(tile)) {
            return Some(SpatialPlacementError::Tree);
        }
        if tiles.iter().any(|&tile| self.has_uncleared_rock(tile)) {
            return Some(SpatialPlacementError::Rock);
        }
        if tiles.iter().any(|tile| self.mountain_tiles.contains(tile)) {
            return Some(SpatialPlacementError::Mountain);
        }
        if tiles.iter().any(|&tile| self.is_perimeter(tile)) {
            return Some(SpatialPlacementError::PerimeterWall);
        }
        if tiles
            .iter()
            .any(|tile| self.paved_road_tiles.contains(tile))
        {
            return Some(SpatialPlacementError::Road);
        }
        if tiles
            .iter()
            .any(|tile| self.reserved_road_tiles.contains(tile))
        {
            return Some(SpatialPlacementError::Road);
        }
        None
    }

    fn road_placement_error(&self, tile: TilePos) -> Option<SpatialPlacementError> {
        if !tile_coordinates_supported(tile) || !self.mapped_tiles.contains(&tile) {
            return Some(SpatialPlacementError::UnmappedTerrain);
        }
        if self.shrine_tiles.contains(&tile) || self.paved_road_tiles.contains(&tile) {
            return None;
        }
        if self.reserved_road_tiles.contains(&tile) {
            return Some(SpatialPlacementError::Road);
        }
        if self.building_tiles.contains(&tile) {
            return Some(SpatialPlacementError::Building);
        }
        if self.has_road_blocking_stockpile(tile) {
            return Some(SpatialPlacementError::Stockpile);
        }
        if self.has_farm(tile) {
            return Some(SpatialPlacementError::Farm);
        }
        if self.water_tiles.contains(&tile) {
            return Some(SpatialPlacementError::Water);
        }
        if self.growing_tree_tiles.contains(&tile) {
            return Some(SpatialPlacementError::Tree);
        }
        if self.has_uncleared_tree(tile) {
            return Some(SpatialPlacementError::Tree);
        }
        if self.has_uncleared_rock(tile) {
            return Some(SpatialPlacementError::Rock);
        }
        if self.mountain_tiles.contains(&tile) {
            return Some(SpatialPlacementError::Mountain);
        }
        self.is_perimeter(tile)
            .then_some(SpatialPlacementError::PerimeterWall)
    }

    fn shrine_connected_road_tiles_excluding(
        &self,
        excluded: &HashSet<TilePos>,
    ) -> HashSet<TilePos> {
        if self.shrine_tiles.is_empty() {
            return HashSet::new();
        }

        let mut connected = self.shrine_tiles.clone();
        let mut queue: VecDeque<TilePos> = self.shrine_tiles.iter().copied().collect();
        while let Some(current) = queue.pop_front() {
            for (dx, dy) in [(0, -1), (1, 0), (0, 1), (-1, 0)] {
                let next = TilePos {
                    x: current.x + dx,
                    y: current.y + dy,
                };
                if connected.contains(&next)
                    || excluded.contains(&next)
                    || !self.paved_road_tiles.contains(&next)
                {
                    continue;
                }
                connected.insert(next);
                queue.push_back(next);
            }
        }
        connected
    }
}

impl pathfinding::SoftObstacleField for SpatialOccupancyContext {
    fn is_soft_obstacle(&self, x: i32, y: i32) -> bool {
        let tile = TilePos { x, y };
        self.has_uncleared_tree(tile) || self.has_uncleared_rock(tile)
    }
}

/// Cheap per-pass view of the persistent derived decoration cache. The expensive
/// climate generation happens once per mapped chunk; A* then performs only set
/// lookups while retaining the exact full rendered footprint.
struct MovementDecorationObstacles {
    mapped_tiles: HashSet<TilePos>,
    cleared_tiles: HashSet<TilePos>,
    trees: HashSet<TilePos>,
    rocks: HashSet<TilePos>,
}

impl MovementDecorationObstacles {
    fn new(colony: &ColonyRuntime, world_seed: u32) -> Self {
        let mapped_tiles = colony.world_tiles.keys().copied().collect::<HashSet<_>>();
        let chunks = mapped_tiles
            .iter()
            .map(|tile| {
                (
                    tile.x.div_euclid(crate::terrain_gen::TERRAIN_CHUNK_SIZE),
                    tile.y.div_euclid(crate::terrain_gen::TERRAIN_CHUNK_SIZE),
                )
            })
            .collect::<BTreeSet<_>>();
        let mut trees = HashSet::new();
        let mut rocks = HashSet::new();
        for (chunk_x, chunk_y) in chunks {
            if let Some(anchors) = colony
                .decoration_cache
                .anchors(world_seed, chunk_x, chunk_y)
            {
                trees.extend(anchors.trees.iter().copied());
                rocks.extend(anchors.rocks.iter().copied());
            }
        }
        Self {
            mapped_tiles,
            cleared_tiles: colony
                .world_tiles
                .iter()
                .filter_map(|(&pos, tile)| {
                    (runtime_decoration_cleared(tile) || inside_village_interior(colony, pos))
                        .then_some(pos)
                })
                .collect(),
            trees,
            rocks,
        }
    }
}

impl pathfinding::SoftObstacleField for MovementDecorationObstacles {
    fn is_soft_obstacle(&self, x: i32, y: i32) -> bool {
        let tile = TilePos { x, y };
        if !self.mapped_tiles.contains(&tile) || self.cleared_tiles.contains(&tile) {
            return false;
        }
        let tree = ((y - (crate::terrain_gen::TREE_FOOTPRINT_HEIGHT - 1))..=y).any(|anchor_y| {
            ((x - (crate::terrain_gen::TREE_FOOTPRINT_WIDTH - 1))..=x).any(|anchor_x| {
                self.trees.contains(&TilePos {
                    x: anchor_x,
                    y: anchor_y,
                })
            })
        });
        tree || self.rocks.contains(&tile)
    }
}

/// Build the one per-tick fine-biome surface table shared by A* and physical
/// movement. Terrain chunks are already warm in [`DecorationCache`], so this is
/// one hash lookup per mapped tile rather than one full chunk regeneration per
/// A* candidate or moving cat.
fn movement_surface_factors(colony: &ColonyRuntime, world_seed: u32) -> HashMap<PathTilePos, f64> {
    movement_surface_factors_from_cache(colony, world_seed, &colony.decoration_cache)
}

fn movement_surface_factors_from_cache(
    colony: &ColonyRuntime,
    world_seed: u32,
    cache: &DecorationCache,
) -> HashMap<PathTilePos, f64> {
    let claimed = colony.claimed_tiles.iter().copied().collect::<HashSet<_>>();
    colony
        .world_tiles
        .iter()
        .map(|(&pos, tile)| {
            let generated = cache
                .climate_biome(world_seed, pos)
                .unwrap_or(crate::climate::Biome::Plains);
            // Settlement clearing is authoritative simulation state: the
            // walled, non-agricultural claim has meadow footing even when the
            // procedural climate underneath was sand, swamp, or mountain.
            let biome = if claimed.contains(&pos)
                && !colony.agricultural_tiles.contains(&pos)
                && !tile_has_water(Some(tile))
            {
                crate::climate::Biome::Meadow
            } else {
                generated
            };
            let factor = if biome.properties().move_factor > 0.0 {
                biome.properties().move_factor
            } else {
                crate::movement::terrain_surface_factor(biome.surface_role())
            };
            (PathTilePos { x: pos.x, y: pos.y }, factor)
        })
        .collect()
}

/// Hard safety envelope for player-authored/world-routed coordinates. The live map is
/// many orders of magnitude smaller; this bound prevents hostile legacy/action values
/// from overflowing terrain chunk origins before the mapped-terrain check rejects them.
const SPATIAL_COORD_LIMIT: i32 = 1_000_000;

fn tile_coordinates_supported(tile: TilePos) -> bool {
    i64::from(tile.x).abs() <= i64::from(SPATIAL_COORD_LIMIT)
        && i64::from(tile.y).abs() <= i64::from(SPATIAL_COORD_LIMIT)
}

fn placement_error_for_tiles(
    colony: &ColonyRuntime,
    tiles: &[TilePos],
    world_seed: u32,
    require_claimed: bool,
) -> Option<SpatialPlacementError> {
    SpatialOccupancyContext::new(colony, world_seed)
        .placement_error_for_tiles(tiles, require_claimed)
}

/// Validate a new stockpile/gather-spot rectangle without mutating the colony.
/// General stockpiles pass `require_claimed = true`; temporary P16 gather spots
/// remain legal outside the village but obey every collision/terrain rule.
#[must_use]
pub fn stockpile_placement_error(
    colony: &ColonyRuntime,
    rect: ZoneRect,
    world_seed: u32,
    require_claimed: bool,
) -> Option<SpatialPlacementError> {
    let Some((width, height)) = stockpiles::rect_dimensions(rect) else {
        return Some(SpatialPlacementError::InvalidRectangle);
    };
    let Ok(width) = i32::try_from(width) else {
        return Some(SpatialPlacementError::InvalidRectangle);
    };
    let Ok(height) = i32::try_from(height) else {
        return Some(SpatialPlacementError::InvalidRectangle);
    };
    let tiles = footprint_tiles(
        TilePos {
            x: rect.x1,
            y: rect.y1,
        },
        width,
        height,
    );
    if tiles.iter().any(|tile| {
        !tile_coordinates_supported(*tile)
            || (!require_claimed
                && (!colony.world_tiles.contains_key(tile)
                    || !colony.revealed_tiles.contains(tile)))
    }) {
        return Some(SpatialPlacementError::UnmappedTerrain);
    }
    placement_error_for_tiles(colony, &tiles, world_seed, require_claimed)
}

/// Building tiles that act as P14.2 soft obstacles. The shrine remains fully
/// passable. Natural decoration anchors are checked per moving cat below rather
/// than regenerating every mapped terrain chunk on every tick.
fn soft_obstacle_tiles(colony: &ColonyRuntime) -> HashSet<TilePos> {
    colony
        .buildings
        .iter()
        .filter(|building| building.building_type != BuildingType::Shrine)
        .flat_map(building_footprint_tiles)
        .collect()
}

/// Whether `tile` sits on the fence perimeter (the palisade wall ring): a tile that
/// is *not* claimed village ground but orthogonally borders it. Buildings must not
/// straddle the wall — since placement also requires the whole footprint to lie
/// inside `claimed_tiles`, perimeter tiles are excluded both ways.
fn tile_is_on_fence_perimeter(claimed: &HashSet<TilePos>, tile: TilePos) -> bool {
    if claimed.contains(&tile) {
        return false;
    }
    [(1, 0), (-1, 0), (0, 1), (0, -1)].iter().any(|(dx, dy)| {
        claimed.contains(&TilePos {
            x: tile.x + dx,
            y: tile.y + dy,
        })
    })
}

/// Whether `tile` can host (part of) a building footprint. True when the tile is
/// already covered by another building, holds water, holds a (client-rendered,
/// terrain-generated) tree, or lies on the fence perimeter (wall).
///
/// `world_seed` is required for the deterministic tree query — trees are otherwise
/// client-only, so the sim reconstructs them from the same terrain generator the
/// renderer uses (see [`crate::terrain_gen::tile_has_tree`]).
#[must_use]
pub fn tile_is_occupied(colony: &ColonyRuntime, tile: TilePos, world_seed: u32) -> bool {
    SpatialOccupancyContext::new(colony, world_seed).tile_is_occupied(tile)
}

#[must_use]
pub(crate) fn occupied_farm_tiles(
    colony: &ColonyRuntime,
    rect: ZoneRect,
    world_seed: u32,
) -> HashSet<TilePos> {
    let occupancy = SpatialOccupancyContext::new(colony, world_seed);
    farming::rect_tiles(rect)
        .map(|tile| TilePos {
            x: tile.x,
            y: tile.y,
        })
        .filter(|tile| occupancy.farm_tile_is_occupied(*tile))
        .collect()
}

#[must_use]
pub(crate) fn farm_rect_touches_claim_boundary(colony: &ColonyRuntime, rect: ZoneRect) -> bool {
    farming::rect_tiles(rect).any(|tile| {
        [
            TilePos {
                x: tile.x,
                y: tile.y - 1,
            },
            TilePos {
                x: tile.x + 1,
                y: tile.y,
            },
            TilePos {
                x: tile.x,
                y: tile.y + 1,
            },
            TilePos {
                x: tile.x - 1,
                y: tile.y,
            },
        ]
        .into_iter()
        .any(|neighbor| !colony.claimed_tiles.contains(&neighbor))
    })
}

fn all_farms_touch_claim_boundary(colony: &ColonyRuntime) -> bool {
    colony
        .farms
        .iter()
        .all(|plot| farm_rect_touches_claim_boundary(colony, plot.rect))
}

