    #[test]
    fn raw_chain_preemption_never_cancels_player_quarries_or_returning_cargo() {
        let mut player = adult_idle_cat("player-quarrier", "colony-1");
        let mut carrier = adult_idle_cat("returning-carrier", "colony-1");
        carrier.activity = CatActivity::Returning;
        carrier.carrying = Some(Carrying {
            kind: CarryingKind::Materials,
            amount: 5.0,
            job_ended_at: 500,
            source_gather_spot: None,
        });
        let automated = adult_idle_cat("leader-quarrier", "colony-1");
        player.current_task = Some(TaskType::Build);
        let quarry = |id: &str, requester, cat_id: &str, status| JobRuntime {
            id: id.to_owned(),
            kind: JobKind::Quarry,
            status,
            requested_by: requester,
            assigned_cat: Some(cat_id.to_owned()),
            ..JobRuntime::default()
        };
        let mut colony = ColonyRuntime {
            id: "colony-1".to_owned(),
            cats: vec![player, carrier, automated],
            jobs: vec![
                quarry(
                    "player-order",
                    JobRequester::Player,
                    "player-quarrier",
                    JobStatus::Queued,
                ),
                quarry(
                    "physical-cargo",
                    JobRequester::Leader,
                    "returning-carrier",
                    JobStatus::Active,
                ),
                quarry(
                    "excess-automation",
                    JobRequester::Leader,
                    "leader-quarrier",
                    JobStatus::Queued,
                ),
            ],
            ..ColonyRuntime::default()
        };

        assert!(release_one_leader_quarry_worker(&mut colony, 1_000));
        let status = |id: &str| {
            colony
                .jobs
                .iter()
                .find(|job| job.id == id)
                .expect("fixture job exists")
                .status
        };
        assert_eq!(status("excess-automation"), JobStatus::Cancelled);
        assert_eq!(status("player-order"), JobStatus::Queued);
        assert_eq!(status("physical-cargo"), JobStatus::Active);
        assert!(
            !release_one_leader_quarry_worker(&mut colony, 2_000),
            "only a player order and a physical return remain"
        );
        let carrier = colony
            .cats
            .iter()
            .find(|cat| cat.id == "returning-carrier")
            .unwrap();
        assert_eq!(carrier.activity, CatActivity::Returning);
        assert_eq!(carrier.carrying.as_ref().unwrap().amount, 5.0);
    }

    #[test]
    fn raw_material_chain_refills_and_crafts_repeated_tools_at_live_cadence() {
        let seed = 4242;
        let mut world = new_world(seed);
        world
            .colonies
            .push(found_colony(seed, "colony-1", 10_000, seed));
        provision_established_roster(&mut world.colonies[0], 10);
        establish_office(&mut world.colonies[0], OfficerRole::Forester);
        let colony = &mut world.colonies[0];
        colony.jobs.clear();
        colony.resources.food = 200.0;
        colony.resources.water = 200.0;
        colony.resources.materials = 100.0;
        colony.resources.stone = 100.0;
        colony.resources.planks = 0.0;
        colony.resources.blocks = 0.0;
        colony.resources.tools = 0.0;
        colony.resources.logs = 100.0;
        colony.test_time_scale = 60.0;
        reconcile_colony_stockpiles(colony);
        let starting_raw = colony.resources.logs + colony.resources.stone;
        let mut twin = world.clone();

        let mut first_tool_second = None;
        let mut second_tool_second = None;
        let mut stages = [false; 8];
        for second in 1..=300_i64 {
            let reports = world_tick(&mut world, 10_000 + second * 1_000);
            let twin_reports = world_tick(&mut twin, 10_000 + second * 1_000);
            assert_eq!(reports, twin_reports, "deterministic twin second {second}");
            assert_eq!(reports[0].reset_reason, None, "second {second}");
            let colony = &world.colonies[0];
            let station = |building_type| {
                colony
                    .buildings
                    .iter()
                    .find(|building| building.building_type == building_type)
                    .unwrap()
            };
            let wood_cutter = station(BuildingType::WoodCutter);
            let stone_prep = station(BuildingType::StonePrep);
            let woodworking = station(BuildingType::Woodworking);
            stages[0] |= building_station_inventory(colony, wood_cutter, true)
                .contains(&(ResourceKind::Planks, 1.0));
            stages[1] |= building_station_inventory(colony, stone_prep, true)
                .contains(&(ResourceKind::Blocks, 1.0));
            let inbound = building_station_cargo(colony, woodworking, "in");
            let input = building_station_inventory(colony, woodworking, false);
            stages[2] |= inbound.contains(&(ResourceKind::Planks, 2.0));
            stages[3] |= input.contains(&(ResourceKind::Planks, 2.0));
            stages[4] |= inbound.contains(&(ResourceKind::Blocks, 2.0));
            stages[5] |= input.contains(&(ResourceKind::Blocks, 2.0));
            stages[6] |= building_station_inventory(colony, woodworking, true)
                .contains(&(ResourceKind::Tools, 1.0));
            stages[7] |= building_station_cargo(colony, woodworking, "out")
                .contains(&(ResourceKind::Tools, 1.0));
            let tools = colony.resources.tools;
            if tools >= 1.0 && first_tool_second.is_none() {
                first_tool_second = Some(second);
            }
            if tools >= 2.0 {
                second_tool_second = Some(second);
                break;
            }
        }

        let first = first_tool_second.expect("raw refineries never funded the first tool");
        let second = second_tool_second.unwrap_or_else(|| {
            let colony = &world.colonies[0];
            panic!(
                "raw chain never repeated a second tool cycle: first={first}s resources={:?} jobs={:?} benches={:?}",
                colony.resources,
                active_or_queued_jobs(colony)
                    .iter()
                    .map(|job| (job.kind, job.status, job.requested_by, job.assigned_cat.as_deref()))
                    .collect::<Vec<_>>(),
                colony
                    .buildings
                    .iter()
                    .filter(|building| RAW_MATERIAL_WORKSHOPS.contains(&building.building_type))
                    .map(|building| (
                        building.building_type,
                        building.assigned_cat.as_deref(),
                        building.automated_by,
                        building.production_progress,
                    ))
                    .collect::<Vec<_>>(),
            )
        });
        let colony = &world.colonies[0];
        eprintln!(
            "organic live tool chain: first={first}s second={second}s logs={:.1} stone={:.1} planks={:.1} blocks={:.1}",
            colony.resources.logs,
            colony.resources.stone,
            colony.resources.planks,
            colony.resources.blocks
        );
        assert!(first < second && second <= 300);
        assert_eq!(
            stages, [true; 8],
            "passive Forester twin missed a real upstream or Woodworking stage"
        );
        assert_eq!(world, twin, "passive Forester twin diverged");
        assert!(colony.resources.logs + colony.resources.stone < starting_raw);
        assert!(colony.resources.tools >= 2.0);
    }

    #[derive(Debug, PartialEq, Eq)]
    struct JobTraceEntry(JobKind, JobStatus, Option<i64>, Option<i64>, Option<i64>);

    #[derive(Debug, PartialEq, Eq)]
    struct QuarryToolOutcome {
        quarry_pos: TilePos,
        first_deposit_second: i64,
        first_tool_second: i64,
        materials_bits: u64,
        stone_bits: u64,
        planks_bits: u64,
        blocks_bits: u64,
        tools_bits: u64,
        job_trace: Vec<JobTraceEntry>,
    }

    fn run_real_quarry_to_tool_campaign(seed: u32) -> QuarryToolOutcome {
        let mut world = new_world(seed);
        world
            .colonies
            .push(found_colony(seed, "colony-1", 10_000, seed));
        provision_established_roster(&mut world.colonies[0], 10);
        establish_office(&mut world.colonies[0], OfficerRole::Forester);
        let colony = &mut world.colonies[0];
        colony.jobs.clear();
        colony.resources.food = 200.0;
        colony.resources.water = 200.0;
        // The signed quarry must physically source the Stone Prep side from an
        // exactly empty raw-Stone store. Seeded Logs below fund the independent
        // physical Wood Cutter side; Supplies are not a timber substitute.
        colony.resources.materials = 40.0;
        colony.resources.stone = 0.0;
        // Bank every non-Stone half of one tool recipe. The campaign isolates the
        // missing final Block so its signed quarry is the sole enabling input.
        colony.resources.planks =
            TOOL_BUILD_MATERIAL_RESERVE + crate::production::WOODWORKING_PLANKS_PER_CYCLE;
        colony.resources.blocks = TOOL_BUILD_MATERIAL_RESERVE
            + crate::production::WOODWORKING_BLOCKS_PER_CYCLE
            - crate::production::WORKSHOP_REFINED_PER_CYCLE;
        colony.resources.tools = 0.0;
        colony.test_time_scale = 60.0;
        // Keep the sibling sawmill's logging faucet satisfied so the one reserved
        // refinery paw proves the quarry→Stone→Blocks→tool chain itself.
        colony.resources.logs = storage_caps(colony).logs;
        reconcile_colony_stockpiles(colony);
        let center = shrine_center_tile(colony.anchor);
        // The mature-claim helper intentionally clears its expansion square to safe
        // meadow. Seed one scout-discovered, unoccupied edge tile as mountains; all
        // travel, extraction, cargo, return and deposit behavior below is production.
        let quarry_pos = colony
            .world_tiles
            .keys()
            .copied()
            .filter(|pos| cheb_from_anchor(center, *pos) >= 12)
            .find(|pos| !tile_is_occupied(colony, *pos, seed))
            .expect("mature world needs an unoccupied discovered stone site");
        let quarry_site = colony
            .world_tiles
            .get_mut(&quarry_pos)
            .expect("selected quarry tile exists");
        quarry_site.tile_type = TileType::Mountains;
        quarry_site.danger_level = 0.0;
        colony.revealed_tiles.insert(quarry_pos);

        let action = proto::ClientAction::RequestJob {
            session_id: "tool-chain-session".to_owned(),
            nickname: "Toolsmith".to_owned(),
            sig: "pure-sim".to_owned(),
            kind: proto::JobKind::Quarry,
        };
        let result = apply_action(
            &mut world,
            &action,
            &ActionCtx {
                session_id: "tool-chain-session".to_owned(),
                player_id: "tool-chain-player".to_owned(),
                colony_id: "colony-1".to_owned(),
                now_ms: 10_500,
            },
        );
        assert!(
            result.ok,
            "signed quarry order failed: {:?}",
            result.message
        );

        let mut saw_real_quarry_job = false;
        let mut saw_returning_stone = false;
        let mut first_deposit_second = None;
        let mut first_tool_second = None;
        for second in 1..=1_200_i64 {
            let reports = world_tick(&mut world, 10_000 + second * 1_000);
            assert_eq!(reports[0].reset_reason, None, "second {second}");
            let colony = &world.colonies[0];
            saw_real_quarry_job |= colony.jobs.iter().any(|job| {
                job.kind == JobKind::Quarry
                    && matches!(job.status, JobStatus::Queued | JobStatus::Active)
            });
            saw_returning_stone |= colony.cats.iter().any(|cat| {
                cat.death_time.is_none()
                    && cat.activity == CatActivity::Returning
                    && cat.carrying.as_ref().is_some_and(|cargo| {
                        cargo.kind == CarryingKind::Stone && cargo.amount > 0.0
                    })
            });
            if colony.resources.stone > 0.0 && first_deposit_second.is_none() {
                first_deposit_second = Some(second);
            }
            if colony.resources.tools > 0.0 {
                first_tool_second = Some(second);
                break;
            }
        }

        let deposit = first_deposit_second.expect("quarriers never returned Stone to storage");
        let tool = first_tool_second.unwrap_or_else(|| {
            let colony = &world.colonies[0];
            panic!(
                "returned quarry Stone never became a tool: stone={:.1} supplies={:.1} planks={:.1} blocks={:.1} jobs={:?} benches={:?}",
                colony.resources.stone,
                colony.resources.materials,
                colony.resources.planks,
                colony.resources.blocks,
                active_or_queued_jobs(colony)
                    .iter()
                    .map(|job| (job.kind, job.assigned_cat.as_deref()))
                    .collect::<Vec<_>>(),
                colony
                    .buildings
                    .iter()
                    .filter(|building| RAW_MATERIAL_WORKSHOPS.contains(&building.building_type))
                    .map(|building| (
                        building.building_type,
                        building.assigned_cat.as_deref(),
                        building.production_progress,
                    ))
                    .collect::<Vec<_>>(),
            )
        });
        eprintln!(
            "live gather→return→refine→craft: quarry={quarry_pos:?} deposit={deposit}s tool={tool}s"
        );
        assert!(
            saw_real_quarry_job,
            "campaign never entered the real Quarry job path"
        );
        assert!(
            saw_returning_stone,
            "campaign never observed physical Stone cargo returning"
        );
        assert!(deposit < tool && tool <= 1_200);
        let colony = &world.colonies[0];
        assert!(colony.resources.tools >= 1.0);
        QuarryToolOutcome {
            quarry_pos,
            first_deposit_second: deposit,
            first_tool_second: tool,
            materials_bits: colony.resources.materials.to_bits(),
            stone_bits: colony.resources.stone.to_bits(),
            planks_bits: colony.resources.planks.to_bits(),
            blocks_bits: colony.resources.blocks.to_bits(),
            tools_bits: colony.resources.tools.to_bits(),
            job_trace: colony
                .jobs
                .iter()
                .map(|job| {
                    JobTraceEntry(
                        job.kind,
                        job.status,
                        job.started_at,
                        job.ends_at,
                        job.completed_at,
                    )
                })
                .collect(),
        }
    }

    #[test]
    fn signed_quarry_return_funds_a_non_starter_tool_at_one_second_cadence_deterministically() {
        let left = run_real_quarry_to_tool_campaign(4242);
        let right = run_real_quarry_to_tool_campaign(4242);
        assert_eq!(left, right, "identical live-cadence campaigns diverged");
    }

    #[test]
    fn colony_runtime_add_and_remove_item_delegate_to_the_items_store() {
        use crate::items::{ItemKind, Material};

        let mut colony = ColonyRuntime::default();
        let mug = Item::new(ItemKind::Mug, Material::Wood, 1);

        colony.add_item(mug, 3);
        colony.add_item(mug, 2);
        assert_eq!(colony.items.get(&mug), Some(&5));

        assert!(!colony.remove_item(mug, 10), "insufficient count fails");
        assert_eq!(
            colony.items.get(&mug),
            Some(&5),
            "store untouched on failure"
        );

        assert!(colony.remove_item(mug, 5));
        assert!(!colony.items.contains_key(&mug), "entry dropped at zero");
    }

