    // ---- P12.1 skills ----

    #[test]
    fn skill_scaled_yield_is_monotonic_and_zero_matches_base() {
        let mut cat = adult_idle_cat("q", "colony-1");
        // At skill 0 the whole-number quarry base is returned unchanged.
        assert_eq!(
            skill_scaled_yield(&cat, JobKind::Quarry, QUARRY_TOTAL_YIELD),
            QUARRY_TOTAL_YIELD
        );

        cat.gain_skill(Labor::Quarry, 30.0);
        let mid = skill_scaled_yield(&cat, JobKind::Quarry, QUARRY_TOTAL_YIELD);
        assert!(mid > QUARRY_TOTAL_YIELD);

        cat.gain_skill(Labor::Quarry, 100_000.0);
        let high = skill_scaled_yield(&cat, JobKind::Quarry, QUARRY_TOTAL_YIELD);
        assert!(high >= mid);
        // Bounded by the 1.4x yield asymptote.
        assert!(high <= (QUARRY_TOTAL_YIELD * 1.4).ceil());

        // A labor-less job kind is never scaled.
        assert_eq!(
            skill_scaled_yield(&cat, JobKind::Explore, QUARRY_TOTAL_YIELD),
            QUARRY_TOTAL_YIELD
        );
    }

    /// Builds a single quarry job assigned to `cat_id`, hauling from `site`, ready
    /// for its first trip's total-yield computation.
    fn quarry_job_at(site: TilePos, cat_id: &str) -> JobRuntime {
        JobRuntime {
            id: "quarry-1".to_owned(),
            kind: JobKind::Quarry,
            status: JobStatus::Active,
            requested_by: JobRequester::Leader,
            assigned_cat: Some(cat_id.to_owned()),
            duration_ms: 1_000,
            speed: 1.0,
            yield_amount: 0.0,
            click_count: 0,
            created_at: 0,
            started_at: Some(0),
            ends_at: Some(1_000),
            completed_at: None,
            metadata: JobMetadata::Hauling {
                site: Some(site),
                total_yield: None,
                trips_done: 0,
                next_trip_at: None,
                accepted: true,
            },
        }
    }

    #[test]
    fn quarry_yield_is_biome_gated_full_on_mountain_trickle_on_stony_none_elsewhere() {
        // P17 mining rules, wired end to end through `total_yield_for_job`'s
        // `Quarry` arm: three real sites for seed 42, one per `climate::Mining`
        // rule (found by scanning `tile_climate_biome`, not hardcoded — biome
        // placement is seed noise).
        let seed = 42u32;
        let full_site = pos(200, 573);
        let trickle_site = pos(200, 0);
        let none_site = pos(0, 0);
        assert_eq!(
            crate::terrain_gen::tile_climate_biome(seed, full_site.x, full_site.y)
                .properties()
                .mining,
            crate::climate::Mining::Full,
            "test fixture assumption: full_site mines fully"
        );
        assert_eq!(
            crate::terrain_gen::tile_climate_biome(seed, trickle_site.x, trickle_site.y)
                .properties()
                .mining,
            crate::climate::Mining::Trickle,
            "test fixture assumption: trickle_site gives a trickle"
        );
        assert_eq!(
            crate::terrain_gen::tile_climate_biome(seed, none_site.x, none_site.y)
                .properties()
                .mining,
            crate::climate::Mining::None,
            "test fixture assumption: none_site has no mining rule"
        );

        let colony = ColonyRuntime {
            cats: vec![adult_idle_cat("miner", "colony-1")],
            ..ColonyRuntime::default()
        };

        let full_yield = total_yield_for_job(&colony, &quarry_job_at(full_site, "miner"), 0, seed);
        let trickle_yield =
            total_yield_for_job(&colony, &quarry_job_at(trickle_site, "miner"), 0, seed);
        let none_yield = total_yield_for_job(&colony, &quarry_job_at(none_site, "miner"), 0, seed);

        assert_eq!(
            full_yield, QUARRY_TOTAL_YIELD,
            "a mountain site keeps the full base yield"
        );
        assert!(
            trickle_yield > 0.0 && trickle_yield < full_yield,
            "a stony site should give a nonzero trickle below the full yield, got {trickle_yield}"
        );
        assert_eq!(none_yield, 0.0, "a non-mining biome yields nothing");

        // Deterministic: re-running the same site produces byte-identical yield.
        let twin_yield =
            total_yield_for_job(&colony, &quarry_job_at(trickle_site, "miner"), 0, seed);
        assert_eq!(trickle_yield.to_bits(), twin_yield.to_bits());
    }

    #[test]
    fn resolved_gather_and_material_effects_scale_only_their_truthful_physical_loads() {
        let seed = 42;
        let mountain = pos(200, 573);
        assert_eq!(
            crate::terrain_gen::tile_climate_biome(seed, mountain.x, mountain.y)
                .properties()
                .mining,
            crate::climate::Mining::Full
        );
        let cat = adult_idle_cat("worker", "colony-1");
        let control = ColonyRuntime {
            cats: vec![cat.clone()],
            ..ColonyRuntime::default()
        };

        let mut forage_upgrade = control.clone();
        forage_upgrade
            .upgrade_tree
            .owned_node_ids
            .push("foraging_lore".to_owned());
        let forage_job = JobRuntime {
            kind: JobKind::ForageFibre,
            assigned_cat: Some(cat.id.clone()),
            ..JobRuntime::default()
        };
        let mut forage_control = control.clone();
        complete_fibre_forage(&mut forage_control, &forage_job, production_gate(1, 1_000));
        complete_fibre_forage(&mut forage_upgrade, &forage_job, production_gate(1, 1_000));
        assert_eq!(forage_control.resources.fibre, 0.0);
        assert_eq!(forage_upgrade.resources.fibre, 0.0);
        assert_eq!(
            forage_control.cats[0]
                .carrying
                .as_ref()
                .map(|cargo| (cargo.kind, cargo.amount)),
            Some((CarryingKind::Fibre, FIBRE_FORAGE_YIELD))
        );
        assert_eq!(
            forage_upgrade.cats[0]
                .carrying
                .as_ref()
                .map(|cargo| (cargo.kind, cargo.amount)),
            Some((CarryingKind::Fibre, FIBRE_FORAGE_YIELD * 1.15))
        );

        let quarry = quarry_job_at(mountain, &cat.id);
        let mut logging = quarry.clone();
        logging.id = "logging-1".to_owned();
        logging.kind = JobKind::GatherLogs;
        let control_quarry = total_yield_for_job(&control, &quarry, 0, seed);
        let control_logging = total_yield_for_job(&control, &logging, 0, seed);

        // `foraging_lore` does not silently increase stone or timber. The Sawmill node's
        // material effect owns both explicit material-extraction paths: logs and quarry stone.
        assert_eq!(
            total_yield_for_job(&forage_upgrade, &quarry, 0, seed),
            control_quarry
        );
        assert_eq!(
            total_yield_for_job(&forage_upgrade, &logging, 0, seed),
            control_logging
        );
        let mut material_upgrade = control.clone();
        material_upgrade
            .upgrade_tree
            .owned_node_ids
            .push("sawmill".to_owned());
        assert_eq!(
            total_yield_for_job(&material_upgrade, &quarry, 0, seed),
            (control_quarry * 1.2).floor()
        );
        assert_eq!(
            total_yield_for_job(&material_upgrade, &logging, 0, seed),
            control_logging * 1.2
        );

        assert_eq!(
            quarry.ends_at, logging.ends_at,
            "yield research must not alter completion timing"
        );
        assert_eq!(
            total_yield_for_job(&material_upgrade, &quarry, 0, seed).to_bits(),
            total_yield_for_job(&material_upgrade.clone(), &quarry, 0, seed).to_bits(),
            "same upgrade state and seed must resolve byte-identical loads"
        );
    }

    #[test]
    fn fibre_forage_reserves_real_capacity_across_simultaneous_due_workers() {
        let mut colony = chain_colony(
            BuildingType::Clothier,
            Resources {
                fibre: BASE_CAPACITY.fibre - 1.0,
                ..Resources::default()
            },
            false,
        );
        colony.cats = vec![
            adult_idle_cat("forager-a", "colony-1"),
            adult_idle_cat("forager-b", "colony-1"),
        ];
        for cat_id in ["forager-a", "forager-b"] {
            complete_fibre_forage(
                &mut colony,
                &JobRuntime {
                    kind: JobKind::ForageFibre,
                    assigned_cat: Some(cat_id.to_owned()),
                    ..JobRuntime::default()
                },
                production_gate(1, 1_000),
            );
        }
        let carried = colony
            .cats
            .iter()
            .filter_map(|cat| cat.carrying.as_ref())
            .map(|cargo| cargo.amount)
            .sum::<f64>();
        assert_eq!(carried, 1.0);
        assert_eq!(colony.resources.fibre + carried, BASE_CAPACITY.fibre);
        assert_eq!(
            colony
                .cats
                .iter()
                .filter(|cat| cat.carrying.is_some())
                .count(),
            1
        );
    }

