    #[test]
    fn vacancy_death_and_station_removal_midcarry_preserve_one_durable_cargo() {
        let mut colony = steward_station_colony(true);
        let (source, destination, transit) = prepare_stockpile_balance_pickup(&mut colony);
        let carrying = colony
            .cats
            .iter()
            .find_map(|cat| cat.carrying.clone())
            .expect("haul is in flight");
        let source_capacity = colony
            .stockpiles
            .iter()
            .find(|pile| pile.id == source)
            .and_then(Stockpile::capacity)
            .unwrap();
        stockpiles::set_resource(
            &mut colony
                .stockpiles
                .iter_mut()
                .find(|pile| pile.id == source)
                .unwrap()
                .contents,
            ResourceKind::Grain,
            source_capacity,
        );

        colony.officers.remove(&OfficerRole::Steward);
        sync_steward_managed_piles(&mut colony, 3_000, 7);
        assert!(!colony.stock_ledger.steward_managed_piles[&destination].active);
        assert!(colony.stockpiles.iter().any(|pile| pile.id == destination));
        assert_eq!(
            stockpiles::resource_amount(
                &colony
                    .stockpiles
                    .iter()
                    .find(|pile| pile.id == transit)
                    .expect("vacancy leaves blocked transit")
                    .contents,
                ResourceKind::Grain,
            ),
            carrying.amount
        );

        assert!(salvage_station_cargo(
            &mut colony,
            &carrying,
            WorldPos { x: 0.0, y: 0.0 }
        ));
        assert_eq!(
            stockpiles::resource_amount(
                &colony
                    .stockpiles
                    .iter()
                    .find(|pile| pile.id == transit)
                    .expect("death does not duplicate or delete blocked transit")
                    .contents,
                ResourceKind::Grain,
            ),
            carrying.amount
        );

        colony
            .officers
            .insert(OfficerRole::Steward, "steward-cat".to_owned());
        colony.buildings.retain(|building| building.id != "mill-a");
        sync_steward_managed_piles(&mut colony, 4_000, 7);
        assert!(colony.stockpiles.iter().any(|pile| pile.id == destination));
        assert!(!colony.stock_ledger.steward_managed_piles[&destination].active);
        dispatch_stockpile_balance_haul(&mut colony, 5_000, 7);
        assert_eq!(
            colony
                .jobs
                .iter()
                .filter(|job| matches!(job.metadata, JobMetadata::StockpileHaul { .. }))
                .count(),
            1,
            "unresolved cargo blocks a second balancing route"
        );
    }

    fn reveal_open_cardinal_neighbors(colony: &mut ColonyRuntime, site: TilePos) {
        for tile in [
            TilePos {
                x: site.x,
                y: site.y - 1,
            },
            TilePos {
                x: site.x + 1,
                y: site.y,
            },
            TilePos {
                x: site.x,
                y: site.y + 1,
            },
            TilePos {
                x: site.x - 1,
                y: site.y,
            },
        ] {
            let mut ground = fresh_ground_tile(tile);
            // Field is the runtime marker that any generated tree has already
            // been cleared, making this synthetic fixture unambiguously open.
            ground.tile_type = TileType::Field;
            colony.world_tiles.insert(tile, ground);
            colony.revealed_tiles.insert(tile);
        }
    }

    #[test]
    fn steward_auto_designates_a_gather_spot_beside_a_distant_heavily_worked_site() {
        let mut colony = steward_colony();
        let site = TilePos {
            x: VILLAGE_ANCHOR.x + AUTO_GATHER_SPOT_MIN_DISTANCE + 2,
            y: VILLAGE_ANCHOR.y,
        };
        reveal_open_cardinal_neighbors(&mut colony, site);
        colony.jobs.extend(quarry_pair_at(site));

        phase_p16_gather_spot_logistics(&mut colony, production_gate(1, 5_000), 42);

        assert_eq!(colony.gather_spots.len(), 1, "one spot auto-designated");
        let spot = &colony.gather_spots[0];
        assert_eq!(spot.kind, ResourceKind::Stone);
        assert!(spot.stockpile_id.starts_with("gather-auto-"));
        let pile = colony
            .stockpiles
            .iter()
            .find(|p| p.id == spot.stockpile_id)
            .expect("backing pile present");
        // Adjacent to (not on top of) the site, on the cardinal neighbour closest to the
        // anchor — west, since the site sits due east of it.
        assert_eq!(
            pile.rect,
            tile_rect(site.x - 1, site.y),
            "placed adjacent to the site, biased toward the village"
        );
        assert_eq!(pile.accepts.len(), 1);
        assert!(pile.accepts.contains(&ResourceKind::Stone));
    }

