    #[test]
    fn staffed_production_and_research_train_the_truthful_labor_only() {
        let cases = [
            (
                BuildingType::Mill,
                Resources {
                    grain: 4.0,
                    ..Resources::default()
                },
                Labor::Mill,
            ),
            (
                BuildingType::Sawmill,
                Resources {
                    logs: 5.0,
                    ..Resources::default()
                },
                Labor::Process,
            ),
            (
                BuildingType::WoodCutter,
                Resources {
                    logs: 5.0,
                    ..Resources::default()
                },
                Labor::Process,
            ),
            (
                BuildingType::Workshop,
                Resources {
                    materials: 50.0,
                    ..Resources::default()
                },
                Labor::Process,
            ),
            (
                BuildingType::Woodworking,
                Resources {
                    planks: 30.0,
                    blocks: 30.0,
                    ..Resources::default()
                },
                Labor::Craft,
            ),
            (
                BuildingType::Smelter,
                Resources {
                    ore: 5.0,
                    ..Resources::default()
                },
                Labor::Metalwork,
            ),
            (
                BuildingType::Clothier,
                Resources {
                    fibre: 5.0,
                    ..Resources::default()
                },
                Labor::Textile,
            ),
            (
                BuildingType::Tannery,
                Resources {
                    hide: 5.0,
                    ..Resources::default()
                },
                Labor::Textile,
            ),
        ];

        for (building, resources, expected) in cases {
            let mut colony = chain_colony(building, resources, true);
            if building == BuildingType::Woodworking {
                seed_station_input_at_worker(&mut colony, ResourceKind::Planks, 2.0);
                seed_station_input_at_worker(&mut colony, ResourceKind::Blocks, 2.0);
                phase_23_production(&mut colony, production_gate(30, 30_000), 123);
            } else if is_physical_station(building) {
                // Physical stations cannot complete until their worker has hauled real
                // recipe input from a stockpile into the station-local input store.
                place_chain_worker_at_seeded_store(&mut colony);
                phase_23_production(&mut colony, production_gate(30, 30_000), 123);
                let inbound = colony.cats[0].carrying.clone().expect("input in flight");
                let work_point = station_work_point(&colony.buildings[0]);
                colony.cats[0].position = position_from_world(work_point);
                credit_carrying(&mut colony, &inbound, work_point);
                colony.cats[0].carrying = None;
                phase_23_production(&mut colony, production_gate(30, 60_000), 123);
            } else {
                phase_23_production(&mut colony, production_gate(30, 30_000), 123);
            }
            assert!(
                colony.cats[0].skill(expected) > 0.0,
                "{building:?} completed work without {expected:?} xp"
            );
            assert_eq!(
                colony.cats[0].skills.len(),
                1,
                "{building:?} trained unrelated labors: {:?}",
                colony.cats[0].skills
            );
        }

        let mut field = chain_colony(BuildingType::Field, Resources::default(), true);
        field.farms.push(FarmPlot {
            id: "skill-farm".to_owned(),
            rect: tile_rect(12, 12),
            crop: CropKind::Grain,
            planted_at: 0,
            stage: farming::FarmStage::Soil,
            growth_hours: 0.0,
            fertility: 1.0,
            worker_id: None,
            work_phase: FarmWorkPhase::WaitingForWorker,
            pending_output: 0.0,
        });
        field.cats[0].position = position_from_world(WorldPos { x: 12.0, y: 12.0 });
        phase_23_production(&mut field, production_gate(30, 30_000), 123);
        assert!(field.farms[0].growth_hours > 0.0);
        assert_eq!(field.resources.food, 0.0, "Field stations never mint food");
        assert!(field.cats[0].skill(Labor::Farm) > 0.0);

        let mut research = chain_colony(BuildingType::ResearchHut, Resources::default(), true);
        phase_24_research(&mut research, production_gate(60, 60_000));
        assert!(research.upgrade_tree.research_points > 0.0);
        assert!(research.cats[0].skill(Labor::Research) > 0.0);
    }

