    #[test]
    fn station_skill_monotonically_speeds_work_with_a_bounded_rate() {
        let make = |skill| {
            let mut colony = chain_colony(
                BuildingType::Workshop,
                Resources {
                    materials: 50.0,
                    ..Resources::default()
                },
                true,
            );
            colony.buildings[0].production_progress = 598.7;
            colony.cats[0].gain_skill(Labor::Process, skill);
            colony
        };
        let mut novice = make(0.0);
        let mut practiced = make(30.0);
        let mut expert = make(1_000_000.0);
        for colony in [&mut novice, &mut practiced, &mut expert] {
            move_general_stock_to_station_input(colony, ResourceKind::Materials, 5.0);
            colony.cats[0].position = position_from_world(station_work_point(&colony.buildings[0]));
        }
        phase_23_production(&mut novice, production_gate(1, 1_000), 123);
        phase_23_production(&mut practiced, production_gate(1, 1_000), 123);
        phase_23_production(&mut expert, production_gate(1, 1_000), 123);
        assert!(building_station_inventory(&novice, &novice.buildings[0], true).is_empty());
        assert!(building_station_inventory(&practiced, &practiced.buildings[0], true).is_empty());
        assert_eq!(
            building_station_inventory(&expert, &expert.buildings[0], true),
            vec![(ResourceKind::Refined, 1.0)]
        );
        assert!(
            expert.buildings[0].production_progress <= 598.7 + 4.0 / 3.0,
            "expert work rate exceeded the 4/3 bound"
        );
    }

    #[test]
    fn manual_and_officer_staffed_work_share_one_deterministic_skill_path() {
        let base = chain_colony(
            BuildingType::Workshop,
            Resources {
                materials: 50.0,
                ..Resources::default()
            },
            true,
        );
        let mut manual = base.clone();
        let mut officer = base;
        officer
            .officers
            .insert(OfficerRole::Steward, "crafter".to_owned());
        officer.buildings[0].automated_by = Some(OfficerRole::Steward);
        for colony in [&mut manual, &mut officer] {
            move_general_stock_to_station_input(colony, ResourceKind::Materials, 5.0);
            colony.cats[0].position = position_from_world(station_work_point(&colony.buildings[0]));
        }

        phase_23_production(&mut manual, production_gate(30, 30_000), 123);
        phase_23_production(&mut officer, production_gate(30, 30_000), 123);

        assert_eq!(manual.resources, officer.resources);
        assert_eq!(manual.cats[0].skills, officer.cats[0].skills);
        assert_eq!(manual.cats[0].skill(Labor::Process), SKILL_GAIN_PER_JOB);

        let mut twin = manual.clone();
        phase_23_production(&mut manual, production_gate(30, 60_000), 123);
        phase_23_production(&mut twin, production_gate(30, 60_000), 123);
        assert_eq!(manual.cats[0].skills, twin.cats[0].skills);
        assert_eq!(manual.resources, twin.resources);
    }

    #[test]
    fn raw_benches_never_fall_back_to_one_legacy_supplies_cycle() {
        let run = |order: [BuildingType; 2]| {
            let mut colony = ColonyRuntime {
                id: "colony-1".to_owned(),
                resources: Resources {
                    materials: crate::production::WORKSHOP_MATERIALS_PER_CYCLE,
                    ..Resources::default()
                },
                cats: vec![
                    adult_idle_cat("raw-a", "colony-1"),
                    adult_idle_cat("raw-b", "colony-1"),
                ],
                buildings: order
                    .into_iter()
                    .enumerate()
                    .map(|(index, building_type)| BuildingRuntime {
                        id: format!("raw-{index}"),
                        building_type,
                        level: 1,
                        position: TilePos {
                            x: 12 + index as i32,
                            y: 12,
                        },
                        is_complete: true,
                        construction_progress: 100,
                        production_progress: 590.0,
                        assigned_cat: Some(format!("raw-{}", if index == 0 { 'a' } else { 'b' })),
                        automated_by: None,
                        additional_work_slots: Vec::new(),
                        production_queue: default_production_queue(building_type),
                        production_paused: false,
                        construction_cargo: None,
                    })
                    .collect(),
                last_tick: 0,
                test_rng_seed: Some(1),
                ..ColonyRuntime::default()
            };

            phase_23_production(&mut colony, production_gate(30, 30_000), 123);
            (
                colony.resources.materials,
                colony.resources.planks,
                colony.resources.blocks,
            )
        };

        assert_eq!(
            run([BuildingType::WoodCutter, BuildingType::StonePrep]),
            (5.0, 0.0, 0.0),
            "Supplies alone cannot fund either distinct raw bench"
        );
        assert_eq!(
            run([BuildingType::StonePrep, BuildingType::WoodCutter]),
            (5.0, 0.0, 0.0),
            "vector order cannot restore the removed aggregate fallback"
        );
    }

    #[test]
    fn designated_farm_requires_a_living_field_worker_and_routes_a_harvest_basket() {
        let seed = 123;
        let site = TilePos { x: 12, y: 12 };
        let gather_id = farm_gather_spot_id("farm-1");
        let fertility = crate::terrain_gen::tile_climate_biome(seed, site.x, site.y)
            .properties()
            .fertility;
        assert!(fertility > 0.0, "test site must be farmable");
        let cat = adult_idle_cat("farmer", "colony-1");
        let mut colony = ColonyRuntime {
            id: "colony-1".to_owned(),
            cats: vec![cat],
            farms: vec![FarmPlot {
                id: "farm-1".to_owned(),
                rect: tile_rect(site.x, site.y),
                crop: CropKind::Grain,
                planted_at: 0,
                stage: farming::FarmStage::Soil,
                growth_hours: 0.0,
                fertility,
                worker_id: None,
                work_phase: FarmWorkPhase::WaitingForWorker,
                pending_output: 0.0,
            }],
            stockpiles: vec![designated_pile(
                &gather_id,
                tile_rect(site.x + 1, site.y),
                &[ResourceKind::Grain],
            )],
            gather_spots: vec![GatherSpot {
                stockpile_id: gather_id,
                kind: ResourceKind::Grain,
                expires_at_ms: i64::MAX,
                purpose: GatherSpotPurpose::General,
            }],
            ..ColonyRuntime::default()
        };
        let elapsed = (farming::HARVEST_AT_HOURS / fertility * 3_600.0).ceil() as i64 + 1;

        phase_23_production(&mut colony, production_gate(elapsed, 1_000), seed);
        assert_eq!(colony.resources.grain, 0.0);
        assert_eq!(colony.farms[0].stage, farming::FarmStage::Soil);
        assert_eq!(colony.farms[0].work_phase, FarmWorkPhase::WaitingForWorker);

        colony.buildings.push(BuildingRuntime {
            id: "field-1".to_owned(),
            building_type: BuildingType::Field,
            level: 1,
            position: site,
            is_complete: true,
            construction_progress: 100,
            production_progress: 0.0,
            assigned_cat: Some("farmer".to_owned()),
            automated_by: None,
            additional_work_slots: Vec::new(),
            production_queue: crate::world_tick::default_production_queue(BuildingType::Field),
            production_paused: false,
            construction_cargo: None,
        });
        colony.cats[0].position = position_from_world(WorldPos {
            x: f64::from(site.x),
            y: f64::from(site.y),
        });
        phase_23_production(&mut colony, production_gate(elapsed, 2_000), seed);
        assert_eq!(colony.resources.grain, 0.0, "harvest is not early credit");
        assert!(colony.farms[0].growth_hours < 0.001);
        assert_eq!(colony.farms[0].pending_output, 2.0);
        assert_eq!(colony.farms[0].work_phase, FarmWorkPhase::Harvesting);

        phase_23_production(&mut colony, production_gate(1, 3_000), seed);
        assert_eq!(colony.resources.grain, 0.0, "cargo remains uncredited");
        assert_eq!(
            colony.cats[0].carrying.as_ref().unwrap().kind,
            CarryingKind::Grain
        );
        colony.cats[0].position = position_from_world(WorldPos {
            x: f64::from(site.x + 1),
            y: f64::from(site.y),
        });
        let mut movement = haul_movement_ctx();
        phase_33_movement_deposits_and_no_destination_wander(
            &mut colony,
            production_gate(1, 4_000),
            &mut movement,
        );
        assert_eq!(colony.resources.grain, 2.0);
        assert_eq!(
            colony.stockpiles[0].contents.grain, 2.0,
            "harvest is routed only to the plot-local gather spot"
        );
    }

