    #[test]
    fn physical_sawmill_chooses_nearest_source_and_destination_and_reports_full_storage() {
        let mut colony = chain_colony(
            BuildingType::Sawmill,
            Resources {
                logs: 10.0,
                ..Resources::default()
            },
            true,
        );
        let near_rect = tile_rect(11, 12);
        let mut near = designated_pile("near-logs", near_rect, &[ResourceKind::Logs]);
        near.contents.logs = 5.0;
        colony.stockpiles.push(near);
        reconcile_colony_stockpiles(&mut colony);

        phase_23_production(&mut colony, production_gate(1, 1_000), 123);
        assert_eq!(
            colony.cats[0].destination,
            Some(position_from_world(WorldPos { x: 11.0, y: 12.0 })),
            "the closest stocked source wins"
        );

        // Isolate a completed local output and fill every general destination.
        colony.cats[0].carrying = None;
        colony.cats[0].destination = None;
        colony.stockpiles.retain(|pile| pile.id != "near-logs");
        let building = colony.buildings[0].clone();
        let output_id = stockpiles::station_output_id(&building.id);
        colony
            .stockpiles
            .iter_mut()
            .find(|pile| pile.id == output_id)
            .unwrap()
            .contents
            .lumber = 2.0;
        let caps = storage_caps(&colony);
        for pile in &mut colony.stockpiles {
            if !pile.is_station_local() {
                pile.accepts.insert(ResourceKind::Lumber);
                let capacity = stockpiles::capacity_for(pile, ResourceKind::Lumber, &caps)
                    .unwrap_or(stockpiles::GENERAL_STOREHOUSE_CAPACITY);
                pile.contents.lumber = capacity;
            }
        }
        assert_eq!(
            building_production_block_reason(&colony, &building).as_deref(),
            Some("output_storage_full")
        );

        // Free a nearby destination. The station worker picks it deterministically and
        // the snapshot state becomes an outbound physical haul.
        let mut destination =
            designated_pile("near-lumber", tile_rect(13, 12), &[ResourceKind::Lumber]);
        destination.contents.lumber = stockpiles::STOCKPILE_TILE_CAPACITY - 0.1;
        colony.stockpiles.push(destination);
        colony.cats[0].position = position_from_world(station_work_point(&building));
        phase_23_production(&mut colony, production_gate(1, 2_000), 123);
        let outbound = colony.cats[0].carrying.as_ref().expect("outbound cargo");
        assert_eq!(outbound.kind, CarryingKind::Lumber);
        assert!((outbound.amount - 0.1).abs() <= 1e-9);
        let remainder = building_station_inventory(&colony, &building, true);
        assert_eq!(remainder[0].0, ResourceKind::Lumber);
        assert!(
            (remainder[0].1 - 1.9).abs() <= 1e-9,
            "the uncarried remainder stays physically at the station"
        );
        assert_eq!(
            haul_deposit_target(
                &colony,
                outbound,
                position_to_world(colony.anchor, colony.cats[0].position)
            ),
            WorldPos { x: 13.0, y: 12.0 }
        );
    }

    #[test]
    fn completed_logging_job_fells_one_site_and_credits_logs_only_on_deposit() {
        let site = TilePos { x: 20, y: 20 };
        let mut cat = adult_idle_cat("forester", "colony-1");
        cat.activity = CatActivity::Working;
        cat.position = position_from_world(tile_pos_to_world(site));
        let job = JobRuntime {
            id: "logging-1".to_owned(),
            kind: JobKind::GatherLogs,
            status: JobStatus::Active,
            assigned_cat: Some("forester".to_owned()),
            duration_ms: 1_000,
            created_at: 0,
            started_at: Some(0),
            ends_at: Some(1_000),
            metadata: JobMetadata::Hauling {
                site: Some(site),
                total_yield: Some(LOGGING_TOTAL_YIELD),
                trips_done: HUNT_TRIP_COUNT as u32 - 1,
                next_trip_at: None,
                accepted: true,
            },
            ..JobRuntime::default()
        };
        let mut colony = ColonyRuntime {
            id: "colony-1".to_owned(),
            cats: vec![cat],
            jobs: vec![job],
            world_tiles: BTreeMap::from([(site, tile(site.x, site.y, 63, None))]),
            ..ColonyRuntime::default()
        };
        reconcile_colony_stockpiles(&mut colony);
        let gate = production_gate(1, 1_000);

        phase_29_due_completion_gathering_explore_expansion(&mut colony, gate, 123);
        assert_eq!(
            colony.resources.logs, 0.0,
            "completion creates cargo, not stock"
        );
        let carrying = colony.cats[0].carrying.clone().expect("logs are hauled");
        assert_eq!(carrying.kind, CarryingKind::Logs);
        assert_eq!(
            carrying.amount,
            LOGGING_TOTAL_YIELD / f64::from(HUNT_TRIP_COUNT)
        );
        assert_eq!(
            colony.world_tiles[&site].overlay_feature.as_deref(),
            Some("stump")
        );

        let destination = tile_pos_to_world(colony.anchor);
        credit_carrying(&mut colony, &carrying, destination);
        assert_eq!(
            colony.resources.logs,
            LOGGING_TOTAL_YIELD / f64::from(HUNT_TRIP_COUNT)
        );
        assert_eq!(colony.resources.materials, 0.0);
        assert_eq!(colony.resources.planks, 0.0);
    }

    fn mapped_replant_fixture(seed: u32) -> (ColonyRuntime, TilePos) {
        let site = (-8..=8)
            .flat_map(|chunk_y| (-8..=8).map(move |chunk_x| (chunk_x, chunk_y)))
            .find_map(|(chunk_x, chunk_y)| {
                crate::terrain_gen::resolved_biome_decorations_for_chunks(
                    i64::from(seed),
                    &BTreeSet::from([(chunk_x, chunk_y)]),
                )
                .into_iter()
                .find_map(|((x, y), decoration)| {
                    matches!(decoration, crate::terrain_gen::DecorationRole::Tree { .. })
                        .then_some(TilePos { x, y })
                })
            })
            .expect("bounded terrain contains a tree");
        let mut colony = ColonyRuntime {
            anchor: TilePos {
                x: site.x - 20,
                y: site.y - 20,
            },
            test_time_scale: 1.0,
            ..ColonyRuntime::default()
        };
        for footprint in tree_footprint_tiles(site) {
            colony
                .world_tiles
                .insert(footprint, tile(footprint.x, footprint.y, 63, None));
            colony.revealed_tiles.insert(footprint);
        }
        let stump = colony.world_tiles.get_mut(&site).unwrap();
        stump.overlay_feature = Some("stump".to_owned());
        stump.last_depleted = 10;
        (colony, site)
    }

    fn regrowth_gate(elapsed_sec: i64, processed_through: i64) -> TickGate {
        TickGate {
            minute_rolled: true,
            ..production_gate(elapsed_sec, processed_through)
        }
    }

    #[test]
    fn replanting_consumes_one_stump_only_after_accepted_on_site_work() {
        let seed = 123;
        let (mut colony, site) = mapped_replant_fixture(seed);
        let mut cat = adult_idle_cat("planter", "colony-1");
        cat.position = position_from_world(tile_pos_to_world(site));
        cat.activity = CatActivity::Working;
        colony.cats.push(cat);
        let mut job = JobRuntime {
            id: "replant-1".to_owned(),
            kind: JobKind::ReplantTree,
            status: JobStatus::Active,
            assigned_cat: Some("planter".to_owned()),
            metadata: JobMetadata::Site {
                site,
                accepted: false,
            },
            ..JobRuntime::default()
        };
        colony.jobs.push(job.clone());

        complete_replant_tree(&mut colony, &job, production_gate(1, 1_000), seed);
        assert_eq!(
            colony.world_tiles[&site].overlay_feature.as_deref(),
            Some("stump"),
            "unaccepted work cannot mutate terrain"
        );

        colony.jobs[0].status = JobStatus::Active;
        job.metadata = JobMetadata::Site {
            site,
            accepted: true,
        };
        complete_replant_tree(&mut colony, &job, production_gate(1, 2_000), seed);
        assert_eq!(
            colony.world_tiles[&site].overlay_feature.as_deref(),
            Some("sapling")
        );
        assert_eq!(colony.world_tiles[&site].last_depleted, 2_000);
        assert_eq!(colony.resources, Resources::default());
        assert_eq!(colony.cats[0].skill(Labor::Woodcut), SKILL_GAIN_PER_JOB);
    }

    #[test]
    fn sapling_growth_is_delayed_blocked_retryable_and_restores_the_generated_tree() {
        let seed = 123;
        let (mut colony, site) = mapped_replant_fixture(seed);
        let planted_at = 60_000;
        colony.world_tiles.get_mut(&site).unwrap().overlay_feature = Some("sapling".to_owned());
        colony.world_tiles.get_mut(&site).unwrap().last_depleted = planted_at;

        // Re-revealing/repainting knowledge is idempotent and cannot reset the
        // persisted ecological clock.
        colony.revealed_tiles.insert(site);
        phase_12_resource_regrowth(
            &mut colony,
            regrowth_gate(60, planted_at + 23 * 3_600_000),
            seed,
        );
        assert_eq!(colony.world_tiles[&site].last_depleted, planted_at);
        assert_eq!(
            colony.world_tiles[&site].overlay_feature.as_deref(),
            Some("sapling")
        );
        assert_eq!(
            stockpile_placement_error(
                &colony,
                ZoneRect {
                    x1: site.x,
                    y1: site.y,
                    x2: site.x,
                    y2: site.y,
                },
                seed,
                false,
            ),
            Some(SpatialPlacementError::Tree),
            "new authored occupancy cannot overwrite a growing tree"
        );

        colony.buildings.push(BuildingRuntime {
            id: "blocking-workshop".to_owned(),
            building_type: BuildingType::Workshop,
            position: site,
            construction_progress: 100,
            ..BuildingRuntime::default()
        });
        phase_12_resource_regrowth(
            &mut colony,
            regrowth_gate(60, planted_at + 24 * 3_600_000),
            seed,
        );
        assert_eq!(
            colony.world_tiles[&site].overlay_feature.as_deref(),
            Some("sapling"),
            "blocked growth remains persisted for a later retry"
        );

        colony.buildings.clear();
        phase_12_resource_regrowth(
            &mut colony,
            regrowth_gate(60, planted_at + 24 * 3_600_000 + 60_000),
            seed,
        );
        assert_eq!(colony.world_tiles[&site].overlay_feature, None);
        assert_eq!(colony.world_tiles[&site].last_depleted, 0);
        assert!(
            has_logging_site(&colony, seed),
            "clearing the overlay must restore the exact deterministic mature tree/logging target"
        );
    }

    #[test]
    fn sapling_maturity_is_cadence_partition_deterministic() {
        let seed = 123;
        let (mut one_tick, site) = mapped_replant_fixture(seed);
        one_tick.world_tiles.get_mut(&site).unwrap().overlay_feature = Some("sapling".to_owned());
        one_tick.world_tiles.get_mut(&site).unwrap().last_depleted = 60_000;
        let mut hourly = one_tick.clone();

        phase_12_resource_regrowth(
            &mut one_tick,
            regrowth_gate(24 * 3_600, 60_000 + 24 * 3_600_000),
            seed,
        );
        for hour in 1..=24 {
            phase_12_resource_regrowth(
                &mut hourly,
                regrowth_gate(3_600, 60_000 + hour * 3_600_000),
                seed,
            );
        }
        assert_eq!(hourly.world_tiles, one_tick.world_tiles);
    }

    #[test]
    fn only_an_appointed_forester_automates_replanting() {
        let seed = 123;
        let (mut colony, _) = mapped_replant_fixture(seed);
        colony.resources.food = 100.0;
        colony.resources.water = 100.0;
        colony.cats.push(adult_idle_cat("officer", "colony-1"));
        colony.cats.push(adult_idle_cat("worker", "colony-1"));

        dispatch_officer_resource_jobs(&mut colony, 1_000, seed, true);
        assert!(colony.jobs.is_empty(), "vacancy must remain fully manual");

        colony
            .officers
            .insert(OfficerRole::Forester, "officer".to_owned());
        dispatch_officer_resource_jobs(&mut colony, 2_000, seed, true);
        let jobs = colony
            .jobs
            .iter()
            .filter(|job| job.kind == JobKind::ReplantTree)
            .collect::<Vec<_>>();
        assert_eq!(jobs.len(), 1);
        assert_eq!(jobs[0].requested_by, JobRequester::Leader);
        assert!(jobs[0].assigned_cat.is_some());

        dispatch_officer_resource_jobs(&mut colony, 3_000, seed, true);
        assert_eq!(
            colony
                .jobs
                .iter()
                .filter(|job| job.kind == JobKind::ReplantTree)
                .count(),
            1,
            "automation stays bounded to one active/queued planting job"
        );
    }

