    #[test]
    fn variant_research_gate_and_dead_outbound_carrier_preserve_exact_goods() {
        let recipe_id = crate::station_recipes::GEM_TRINKET_RECIPE_ID;
        let mut colony = chain_colony(
            BuildingType::Workshop,
            Resources {
                gem: 1.0,
                ..Resources::default()
            },
            true,
        );
        colony.recipe_entitlement_rules_version = CURRENT_RECIPE_ENTITLEMENT_RULES_VERSION;
        colony.buildings[0].production_progress = 590.0;
        colony.buildings[0].production_queue = vec![ProductionQueueEntry {
            recipe_id: recipe_id.to_owned(),
            repeat: false,
        }];
        move_general_stock_to_station_input(&mut colony, ResourceKind::Gem, 1.0);
        let building = colony.buildings[0].clone();
        colony.cats[0].position = position_from_world(station_work_point(&building));

        advance_physical_item_recipe_slot(&mut colony, 0, production_gate(10, 10_000), 10.0, false);
        assert_eq!(colony.items.count_kind(ItemKind::Trinket), 0);
        assert_eq!(colony.resources.gem, 1.0);

        colony
            .upgrade_tree
            .owned_node_ids
            .push("trade_goods_staples".to_owned());
        advance_physical_item_recipe_slot(&mut colony, 0, production_gate(10, 20_000), 10.0, false);
        let item_id = colony
            .items
            .instances()
            .next()
            .expect("researched item produced")
            .id
            .clone();
        assert!(begin_station_item_output_haul(
            &mut colony,
            &building,
            0,
            production_gate(1, 21_000),
        ));
        let cargo = colony.cats[0]
            .carrying
            .clone()
            .expect("outbound item cargo");
        assert!(salvage_station_cargo(
            &mut colony,
            &cargo,
            station_work_point(&building),
        ));
        colony.cats[0].carrying = None;
        let recovered = colony.items.instance(&item_id).expect("identity preserved");
        assert!(!recovered.credited);
        assert_eq!(
            recovered.location,
            ItemLocation::Station {
                building_id: building.id,
                compartment: StationCompartment::LocalOutput,
            }
        );
        assert_eq!(colony.resources.gem, 0.0);
    }

    fn run_passive_gem_goods_campaign() -> ColonyRuntime {
        let mut colony = chain_colony(
            BuildingType::Workshop,
            Resources {
                gem: 1.0,
                food: 100.0,
                water: 100.0,
                ..Resources::default()
            },
            true,
        );
        colony.recipe_entitlement_rules_version = 0;
        colony.buildings[0].production_progress = 0.0;
        colony.buildings[0].production_queue = vec![ProductionQueueEntry {
            recipe_id: crate::station_recipes::GEM_TRINKET_RECIPE_ID.to_owned(),
            repeat: false,
        }];
        move_general_stock_to_station_input(&mut colony, ResourceKind::Gem, 1.0);
        let work = station_work_point(&colony.buildings[0]);
        colony.cats[0].position = position_from_world(work);
        for second in 1..=1_200 {
            phase_23_production(
                &mut colony,
                production_gate(1, i64::from(second) * 1_000),
                8_181,
            );
            deliver_all_station_cargo_to_current_targets(&mut colony);
        }
        colony
    }

    #[test]
    fn unattended_material_variant_campaign_is_deterministic_and_delivers_trade_ready_goods() {
        let left = run_passive_gem_goods_campaign();
        let right = run_passive_gem_goods_campaign();
        assert_eq!(left, right, "passive material-variant campaign diverged");
        let item = left.items.instances().next().expect("gem trinket produced");
        assert_eq!(item.item, Item::new(ItemKind::Trinket, Material::Gem, 2));
        assert!(item.credited);
        assert!(item.is_pristine());
        assert!(matches!(item.location, ItemLocation::Stockpile { .. }));
        assert_eq!(left.resources.gem, 0.0);
    }

    fn flush_refiner_output(colony: &mut ColonyRuntime, gate: TickGate) {
        let building = colony.buildings[0].clone();
        colony.cats[0].position = position_from_world(station_work_point(&building));
        colony.cats[0].carrying = None;
        advance_physical_refiner(colony, 0, gate, 0.0, false);
        deliver_station_cargo_to_current_target(colony);
    }

    #[test]
    fn removing_refiner_leaves_local_ledgers_at_footprint_without_early_credit() {
        let mut colony = chain_colony(
            BuildingType::Workshop,
            Resources {
                materials: 5.0,
                ..Resources::default()
            },
            true,
        );
        ensure_station_stores(&mut colony, 0);
        let building = colony.buildings[0].clone();
        let input_id = stockpiles::station_input_id(&building.id);
        let output_id = stockpiles::station_output_id(&building.id);
        let input = colony
            .stockpiles
            .iter_mut()
            .find(|pile| pile.id == input_id)
            .unwrap();
        input.contents.materials = 5.0;
        let storehouse = colony
            .stockpiles
            .iter_mut()
            .find(|pile| pile.is_general_storehouse())
            .unwrap();
        storehouse.contents.materials = 0.0;
        colony
            .stockpiles
            .iter_mut()
            .find(|pile| pile.id == output_id)
            .unwrap()
            .contents
            .refined = 1.0;
        let former_footprint = colony
            .stockpiles
            .iter()
            .find(|pile| pile.id == input_id)
            .map(|pile| {
                let (x, y) = pile.center();
                WorldPos { x, y }
            })
            .unwrap();
        colony.buildings.clear();
        colony.cats[0].position = position_from_world(WorldPos { x: -30.0, y: -30.0 });

        recover_orphaned_station_stores(&mut colony, production_gate(1, 1_000));

        assert_eq!(colony.resources.materials, 5.0);
        assert_eq!(colony.resources.refined, 0.0);
        assert_eq!(
            colony
                .stockpiles
                .iter()
                .find(|pile| pile.id == input_id)
                .unwrap()
                .contents
                .materials,
            5.0
        );
        assert_eq!(
            colony
                .stockpiles
                .iter()
                .find(|pile| pile.id == output_id)
                .unwrap()
                .contents
                .refined,
            1.0
        );
        assert!(colony.cats[0].carrying.is_none());
        assert_eq!(
            colony.cats[0].destination,
            Some(position_from_world(former_footprint)),
            "the only mutation is dispatching a real cat toward the former footprint"
        );
    }

    #[test]
    fn orphan_refiner_output_waits_when_storage_is_full_then_credits_only_on_delivery() {
        let mut colony = chain_colony(
            BuildingType::Workshop,
            Resources {
                refined: BASE_CAPACITY.refined,
                ..Resources::default()
            },
            true,
        );
        ensure_station_stores(&mut colony, 0);
        let building = colony.buildings[0].clone();
        let output_id = stockpiles::station_output_id(&building.id);
        colony
            .stockpiles
            .iter_mut()
            .find(|pile| pile.id == output_id)
            .unwrap()
            .contents
            .refined = 1.0;
        colony.buildings.clear();
        let source = colony
            .stockpiles
            .iter()
            .find(|pile| pile.id == output_id)
            .map(|pile| {
                let (x, y) = pile.center();
                WorldPos { x, y }
            })
            .unwrap();
        colony.cats[0].position = position_from_world(source);

        recover_orphaned_station_stores(&mut colony, production_gate(1, 1_000));
        assert!(colony.cats[0].carrying.is_none());
        assert_eq!(colony.resources.refined, BASE_CAPACITY.refined);
        assert_eq!(
            colony
                .stockpiles
                .iter()
                .find(|pile| pile.id == output_id)
                .unwrap()
                .contents
                .refined,
            1.0
        );

        colony.resources.refined = 0.0;
        colony
            .stockpiles
            .iter_mut()
            .find(|pile| pile.is_general_storehouse())
            .unwrap()
            .contents
            .refined = 0.0;
        recover_orphaned_station_stores(&mut colony, production_gate(1, 2_000));
        let cargo = colony.cats[0]
            .carrying
            .clone()
            .expect("living salvage haul");
        assert_eq!(cargo.kind, CarryingKind::Refined);
        assert_eq!(colony.resources.refined, 0.0);
        assert_eq!(
            colony
                .stockpiles
                .iter()
                .find(|pile| pile.id == output_id)
                .unwrap()
                .contents
                .refined,
            0.0
        );

        let target = haul_deposit_target(&colony, &cargo, source);
        colony.cats[0].position = position_from_world(target);
        colony
            .stockpiles
            .iter_mut()
            .find(|pile| pile.is_general_storehouse())
            .unwrap()
            .contents
            .refined = BASE_CAPACITY.refined;
        colony.resources.refined = BASE_CAPACITY.refined;
        assert_eq!(credit_carrying(&mut colony, &cargo, target), 1.0);
        assert_eq!(
            colony
                .stockpiles
                .iter()
                .find(|pile| pile.id == output_id)
                .unwrap()
                .contents
                .refined,
            0.0,
            "a destination race leaves the remainder in the carrier, not teleported home"
        );
        colony
            .stockpiles
            .iter_mut()
            .find(|pile| pile.is_general_storehouse())
            .unwrap()
            .contents
            .refined = 0.0;
        colony.resources.refined = 0.0;
        assert_eq!(credit_carrying(&mut colony, &cargo, target), 0.0);
        colony.cats[0].carrying = None;
        assert_eq!(colony.resources.refined, 1.0);
    }

    #[test]
    fn death_mid_orphan_refiner_salvage_never_moves_or_credits_cargo() {
        for (output, kind, carrying_kind) in [
            (false, ResourceKind::Ore, CarryingKind::Ore),
            (true, ResourceKind::Metal, CarryingKind::Metal),
        ] {
            let mut colony = chain_colony(
                BuildingType::Smelter,
                Resources {
                    ore: if output { 0.0 } else { 5.0 },
                    ..Resources::default()
                },
                true,
            );
            ensure_station_stores(&mut colony, 0);
            let building = colony.buildings[0].clone();
            let source_id = if output {
                stockpiles::station_output_id(&building.id)
            } else {
                stockpiles::station_input_id(&building.id)
            };
            stockpiles::set_resource(
                &mut colony
                    .stockpiles
                    .iter_mut()
                    .find(|pile| pile.id == source_id)
                    .unwrap()
                    .contents,
                kind,
                if output { 1.0 } else { 5.0 },
            );
            if !output {
                colony
                    .stockpiles
                    .iter_mut()
                    .find(|pile| pile.is_general_storehouse())
                    .unwrap()
                    .contents
                    .ore = 0.0;
            }
            colony.buildings.clear();
            let source = colony
                .stockpiles
                .iter()
                .find(|pile| pile.id == source_id)
                .map(|pile| {
                    let (x, y) = pile.center();
                    WorldPos { x, y }
                })
                .unwrap();
            colony.cats[0].position = position_from_world(source);
            recover_orphaned_station_stores(&mut colony, production_gate(1, 1_000));
            let cargo = colony.cats[0].carrying.clone().expect("salvage cargo");
            assert_eq!(cargo.kind, carrying_kind);
            assert!(salvage_station_cargo(&mut colony, &cargo, source));
            colony.cats[0].carrying = None;

            assert_eq!(
                stockpiles::resource_amount(
                    &colony
                        .stockpiles
                        .iter()
                        .find(|pile| pile.id == source_id)
                        .unwrap()
                        .contents,
                    kind,
                ),
                if output { 1.0 } else { 5.0 }
            );
            assert_eq!(
                stockpiles::resource_amount(&colony.resources, kind),
                if output { 0.0 } else { 5.0 }
            );
        }
    }

    #[test]
    fn demolished_smelter_inbound_transit_reroutes_physically_without_double_credit() {
        let mut colony = chain_colony(
            BuildingType::Smelter,
            Resources {
                ore: 5.0,
                ..Resources::default()
            },
            true,
        );
        place_chain_worker_at_seeded_store(&mut colony);
        let building = colony.buildings[0].clone();
        phase_23_production(&mut colony, production_gate(1, 1_000), 123);
        let cargo = colony.cats[0].carrying.clone().expect("ore inbound");
        let transit_id = stockpiles::station_transit_id(&building.id);
        assert_eq!(
            colony
                .stockpiles
                .iter()
                .find(|pile| pile.id == transit_id)
                .unwrap()
                .contents
                .ore,
            5.0
        );
        colony.buildings.clear();

        recover_orphaned_station_stores(&mut colony, production_gate(1, 2_000));
        assert_eq!(colony.resources.ore, 5.0);
        assert_eq!(
            colony
                .stockpiles
                .iter()
                .find(|pile| pile.id == transit_id)
                .unwrap()
                .contents
                .ore,
            5.0,
            "removal alone leaves the transit ledger at the pickup footprint"
        );

        let from = position_to_world(colony.anchor, colony.cats[0].position);
        let target = haul_deposit_target(&colony, &cargo, from);
        assert_ne!(target, village_anchor_world(colony.anchor));
        colony.cats[0].position = position_from_world(target);
        assert_eq!(credit_carrying(&mut colony, &cargo, target), 0.0);
        colony.cats[0].carrying = None;
        assert_eq!(colony.resources.ore, 5.0);
        assert_eq!(
            colony
                .stockpiles
                .iter()
                .find(|pile| pile.id == transit_id)
                .unwrap()
                .contents
                .ore,
            0.0
        );
        assert_eq!(
            colony
                .stockpiles
                .iter()
                .find(|pile| pile.is_general_storehouse())
                .unwrap()
                .contents
                .ore,
            5.0
        );
    }

