    #[test]
    fn source_cargo_survives_death_and_full_destination_without_aliasing_supplies() {
        let mut colony = ColonyRuntime {
            id: "conservation".to_owned(),
            cats: vec![adult_idle_cat("carrier", "conservation")],
            resources: Resources {
                materials: 13.0,
                ..Resources::default()
            },
            stockpiles: vec![designated_pile(
                "full-stone",
                tile_rect(20, 6),
                &[ResourceKind::Stone],
            )],
            jobs: vec![JobRuntime {
                id: "cancelled-source".to_owned(),
                kind: JobKind::Quarry,
                status: JobStatus::Active,
                assigned_cat: Some("carrier".to_owned()),
                ..JobRuntime::default()
            }],
            ..ColonyRuntime::default()
        };
        colony.stockpiles[0].contents.stone = 100.0;
        colony.cats[0].position = position_from_world(WorldPos { x: 30.0, y: 30.0 });
        colony.cats[0].carrying = Some(Carrying {
            kind: CarryingKind::Stone,
            amount: 4.0,
            job_ended_at: 1_000,
            source_gather_spot: None,
        });
        let cargo = colony.cats[0].carrying.clone().unwrap();
        assert_eq!(
            credit_carrying(&mut colony, &cargo, WorldPos { x: 20.0, y: 6.0 }),
            4.0
        );
        assert_eq!(colony.resources.stone, 0.0);
        assert_eq!(colony.resources.materials, 13.0);

        mark_cat_dead(&mut colony, "carrier", 2_000);
        let corpse_cargo = colony.cats[0]
            .carrying
            .as_ref()
            .expect("finite source cargo remains on the corpse");
        assert_eq!(corpse_cargo.kind, CarryingKind::Stone);
        assert_eq!(corpse_cargo.amount, 4.0);
        assert_eq!(colony.jobs[0].status, JobStatus::Cancelled);
        assert_eq!(colony.resources.stone, 0.0);
        assert_eq!(colony.resources.materials, 13.0);
    }

    #[test]
    fn overdue_source_deadline_defers_completion_until_every_physical_load_exists() {
        fn run() -> (ColonyRuntime, Vec<Carrying>) {
            let site = TilePos { x: 20, y: 6 };
            let mut colony = ColonyRuntime {
                id: "coarse-source".to_owned(),
                cats: vec![adult_idle_cat("quarrier", "coarse-source")],
                jobs: vec![JobRuntime {
                    id: "overdue-quarry".to_owned(),
                    kind: JobKind::Quarry,
                    status: JobStatus::Active,
                    assigned_cat: Some("quarrier".to_owned()),
                    started_at: Some(0),
                    ends_at: Some(1_000),
                    metadata: JobMetadata::Hauling {
                        site: Some(site),
                        total_yield: Some(QUARRY_TOTAL_YIELD),
                        trips_done: 0,
                        next_trip_at: Some(250),
                        accepted: true,
                    },
                    ..JobRuntime::default()
                }],
                ..ColonyRuntime::default()
            };
            colony.cats[0].activity = CatActivity::Working;
            colony.cats[0].position = position_from_world(tile_pos_to_world(site));
            colony
                .world_tiles
                .insert(site, typed_tile(site.x, site.y, TileType::CaveEntrance));

            let mut loads = Vec::new();
            for step in 0..4_i64 {
                let gate = production_gate(5, 5_000 + step * 5_000);
                phase_29_due_completion_gathering_explore_expansion(&mut colony, gate, 42);
                phase_30_due_completion_build_ritual_training_return_mark_done(&mut colony, gate);
                phase_31_mid_job_hauling(&mut colony, gate, 42);
                loads.push(
                    colony.cats[0]
                        .carrying
                        .take()
                        .expect("each overdue visit extracts exactly one physical load"),
                );
                if step < 3 {
                    assert_eq!(colony.jobs[0].status, JobStatus::Active);
                    colony.cats[0].activity = CatActivity::Working;
                    colony.cats[0].destination = None;
                    colony.cats[0].position = position_from_world(tile_pos_to_world(site));
                }
            }
            (colony, loads)
        }

        let (left, loads) = run();
        let (right, right_loads) = run();
        assert_eq!(left, right);
        assert_eq!(loads, right_loads);
        assert_eq!(
            loads.iter().map(|load| load.kind).collect::<Vec<_>>(),
            vec![
                CarryingKind::Stone,
                CarryingKind::Stone,
                CarryingKind::Stone,
                CarryingKind::Materials,
            ]
        );
        assert_eq!(
            loads.iter().take(3).map(|load| load.amount).sum::<f64>(),
            QUARRY_TOTAL_YIELD
        );
        assert_eq!(
            loads[3].amount,
            QUARRY_TOTAL_YIELD * QUARRY_SUPPLIES_YIELD_RATIO
        );
        assert_eq!(left.jobs[0].status, JobStatus::Completed);
        assert_eq!(
            hauling_metadata(&left.jobs[0]).2,
            HUNT_TRIP_COUNT as u32 + 1
        );
    }

    #[test]
    fn woodworking_crafts_tools_from_planks_and_blocks_only_when_both_present() {
        // Both inputs must physically reach the bench before one atomic cycle can
        // consume 2 planks + 2 blocks into one local, uncredited scalar Tool.
        let mut colony = chain_colony(
            BuildingType::Woodworking,
            Resources {
                planks: 10.0,
                blocks: 10.0,
                ..Resources::default()
            },
            true,
        );
        place_chain_worker_at_seeded_store(&mut colony);
        phase_23_production(&mut colony, production_gate(1, 1_000), 123);
        assert_eq!(
            colony.cats[0].carrying.as_ref().unwrap().kind,
            CarryingKind::Planks
        );
        assert_eq!(colony.cats[0].carrying.as_ref().unwrap().amount, 2.0);
        assert_eq!(
            colony.resources,
            Resources {
                planks: 10.0,
                blocks: 10.0,
                ..Resources::default()
            }
        );
        deliver_station_cargo_to_current_target(&mut colony);
        let (store_x, store_y) = colony
            .stockpiles
            .iter()
            .find(|pile| pile.is_general_storehouse())
            .unwrap()
            .center();
        colony.cats[0].position = position_from_world(WorldPos {
            x: store_x,
            y: store_y,
        });
        phase_23_production(&mut colony, production_gate(1, 2_000), 123);
        assert_eq!(
            colony.cats[0].carrying.as_ref().unwrap().kind,
            CarryingKind::Blocks
        );
        assert_eq!(
            colony.resources.planks, 10.0,
            "the first local input is not consumed early"
        );
        deliver_station_cargo_to_current_target(&mut colony);
        colony.cats[0].position = position_from_world(station_work_point(&colony.buildings[0]));
        phase_23_production(&mut colony, production_gate(30, 32_000), 123);
        assert_eq!(
            colony.resources.tools, 0.0,
            "local output is not aggregate credit"
        );
        assert_eq!(colony.resources.planks, 8.0);
        assert_eq!(colony.resources.blocks, 8.0);
        assert_eq!(
            building_station_inventory(&colony, &colony.buildings[0], true),
            vec![(ResourceKind::Tools, 1.0)]
        );

        // Missing blocks → the bench stalls, tools stay at zero.
        let mut starved = chain_colony(
            BuildingType::Woodworking,
            Resources {
                planks: 10.0,
                blocks: 0.0,
                ..Resources::default()
            },
            true,
        );
        phase_23_production(&mut starved, production_gate(30, 30_000), 123);
        assert_eq!(starved.resources.tools, 0.0);
        assert_eq!(starved.resources.planks, 10.0);

        // Exactly 6/6 can spend one 2/2 cycle while preserving the 4/4 build
        // reserve. Anything below that boundary stalls rather than consuming the
        // scaffold reserve.
        let mut at_reserve_boundary = chain_colony(
            BuildingType::Woodworking,
            Resources {
                planks: 6.0,
                blocks: 6.0,
                ..Resources::default()
            },
            true,
        );
        move_general_stock_to_station_input(&mut at_reserve_boundary, ResourceKind::Planks, 2.0);
        move_general_stock_to_station_input(&mut at_reserve_boundary, ResourceKind::Blocks, 2.0);
        at_reserve_boundary.cats[0].position =
            position_from_world(station_work_point(&at_reserve_boundary.buildings[0]));
        phase_23_production(&mut at_reserve_boundary, production_gate(30, 30_000), 123);
        assert_eq!(at_reserve_boundary.resources.tools, 0.0);
        assert_eq!(at_reserve_boundary.resources.planks, 4.0);
        assert_eq!(at_reserve_boundary.resources.blocks, 4.0);

        let mut below_reserve_boundary = chain_colony(
            BuildingType::Woodworking,
            Resources {
                planks: 5.9,
                blocks: 6.0,
                ..Resources::default()
            },
            true,
        );
        move_general_stock_to_station_input(&mut below_reserve_boundary, ResourceKind::Planks, 2.0);
        move_general_stock_to_station_input(&mut below_reserve_boundary, ResourceKind::Blocks, 2.0);
        below_reserve_boundary.cats[0].position =
            position_from_world(station_work_point(&below_reserve_boundary.buildings[0]));
        phase_23_production(
            &mut below_reserve_boundary,
            production_gate(30, 30_000),
            123,
        );
        assert_eq!(below_reserve_boundary.resources.tools, 0.0);
        assert_eq!(below_reserve_boundary.resources.planks, 5.9);
        assert_eq!(below_reserve_boundary.resources.blocks, 6.0);
    }

    #[test]
    fn completed_work_truthfully_wears_a_finite_tool_until_it_breaks() {
        let tool = Item::new(ItemKind::Tool, Material::Wood, 0);
        let mut colony = chain_colony(
            BuildingType::Workshop,
            Resources {
                materials: 200.0,
                ..Resources::default()
            },
            true,
        );
        colony.add_crafted_item(tool, 1);
        let tool_id = colony.items.instances().next().unwrap().id.clone();
        let max_durability = colony.items.instance(&tool_id).unwrap().max_durability;
        let worker_id = colony.cats[0].id.clone();
        colony.items.relocate(
            &tool_id,
            ItemLocation::Equipped {
                cat_id: worker_id.clone(),
            },
        );
        assert_eq!(
            cat_usable_tool_stock(&colony, &worker_id),
            f64::from(crate::productivity::TOOL_PRODUCTIVITY_CAP)
        );

        for use_index in 0..max_durability {
            move_general_stock_to_station_input(&mut colony, ResourceKind::Materials, 5.0);
            colony.cats[0].position = position_from_world(station_work_point(&colony.buildings[0]));
            colony.buildings[0].production_progress = 590.0;
            phase_23_production(
                &mut colony,
                production_gate(30, i64::from(use_index + 1) * 30_000),
                123,
            );
            assert_eq!(
                colony.items.instance(&tool_id).unwrap().durability,
                max_durability - use_index - 1,
                "one completed production cycle causes exactly one use of wear"
            );
            flush_refiner_output(
                &mut colony,
                production_gate(1, i64::from(use_index + 1) * 30_000 + 1_000),
            );
        }

        assert!(colony.items.instance(&tool_id).unwrap().is_broken());
        assert_eq!(colony.items.get(&tool), Some(&1), "broken remains physical");
        assert_eq!(colony.resources.tools, 1.0, "physical pile count remains");
        assert_eq!(
            cat_usable_tool_stock(&colony, &worker_id),
            0.0,
            "broken stops contributing"
        );
        assert_eq!(
            productive_elapsed(30.0, cat_usable_tool_stock(&colony, &worker_id)),
            30.0,
            "a broken tool grants no productivity acceleration"
        );
    }

    #[test]
    fn finite_equipment_migration_is_idempotent_and_projects_whole_legacy_scalars() {
        let mut colony = chain_colony(
            BuildingType::Workshop,
            Resources {
                tools: 2.9,
                weapons: 1.0,
                armor: 1.0,
                ..Resources::default()
            },
            false,
        );
        colony.finite_equipment_rules_version = 0;
        migrate_finite_equipment_authority(&mut colony);
        let ids = colony
            .items
            .instances()
            .map(|instance| instance.id.clone())
            .collect::<Vec<_>>();
        assert_eq!(colony.items.credited_count(ItemKind::Tool), 2);
        assert_eq!(colony.items.credited_count(ItemKind::Weapon), 1);
        assert_eq!(colony.items.credited_count(ItemKind::Armor), 1);
        assert_eq!(colony.resources.tools, 2.0);
        assert_eq!(colony.finite_equipment_rules_version, 1);

        migrate_finite_equipment_authority(&mut colony);
        assert_eq!(
            colony
                .items
                .instances()
                .map(|instance| instance.id.clone())
                .collect::<Vec<_>>(),
            ids
        );
    }

    #[test]
    fn station_output_haul_delivers_the_same_functional_identity_and_credits_it_once() {
        let mut colony = chain_colony(BuildingType::Woodworking, Resources::default(), true);
        colony.finite_equipment_rules_version = CURRENT_FINITE_EQUIPMENT_RULES_VERSION;
        ensure_station_stores(&mut colony, 0);
        let building = colony.buildings[0].clone();
        add_functional_station_output(&mut colony, &building.id, ResourceKind::Tools, 1);
        reconcile_finite_equipment_projections(&mut colony);
        let tool_id = colony
            .items
            .instances()
            .find(|instance| instance.item.kind == ItemKind::Tool)
            .expect("workshop output owns one exact identity")
            .id
            .clone();
        assert!(!colony.items.instance(&tool_id).unwrap().credited);
        assert_eq!(colony.resources.tools, 0.0);

        colony.cats[0].position = position_from_world(station_work_point(&building));
        assert!(begin_station_output_haul(
            &mut colony,
            &building,
            0,
            ResourceKind::Tools,
            production_gate(1, 1_000),
        ));
        let cat_id = colony.cats[0].id.clone();
        assert_eq!(
            colony.items.instance(&tool_id).unwrap().location,
            ItemLocation::Carrier { cat_id }
        );
        assert_eq!(colony.resources.tools, 0.0, "transit is not early credit");

        deliver_station_cargo_to_current_target(&mut colony);
        reconcile_finite_equipment_projections(&mut colony);
        let delivered = colony.items.instance(&tool_id).unwrap();
        assert!(delivered.credited);
        assert!(matches!(delivered.location, ItemLocation::Stockpile { .. }));
        assert_eq!(colony.resources.tools, 1.0);
        assert_eq!(colony.items.count_kind(ItemKind::Tool), 1);
    }

    #[test]
    fn one_exact_tool_completes_the_full_physical_lifecycle_without_duplication() {
        let mut colony = chain_colony(
            BuildingType::Woodworking,
            Resources {
                planks: 10.0,
                ..Resources::default()
            },
            true,
        );
        colony.finite_equipment_rules_version = CURRENT_FINITE_EQUIPMENT_RULES_VERSION;
        ensure_station_stores(&mut colony, 0);
        let building = colony.buildings[0].clone();
        let cat_id = colony.cats[0].id.clone();

        // Craft one finite unit into the station-local output compartment.
        add_functional_station_output(&mut colony, &building.id, ResourceKind::Tools, 1);
        reconcile_finite_equipment_projections(&mut colony);
        let tool_id = colony
            .items
            .instances()
            .find(|instance| instance.item.kind == ItemKind::Tool)
            .expect("one crafted Tool identity")
            .id
            .clone();
        assert_eq!(colony.items.count_kind(ItemKind::Tool), 1);
        assert_eq!(
            colony.resources.tools, 0.0,
            "local output is not owned early"
        );
        assert!(matches!(
            colony.items.instance(&tool_id).unwrap().location,
            ItemLocation::Station {
                compartment: StationCompartment::LocalOutput,
                ..
            }
        ));

        // The same id leaves the bench in one cat's paws, then becomes credited in
        // one real village pile. No compatibility scalar is minted in transit.
        colony.cats[0].position = position_from_world(station_work_point(&building));
        assert!(begin_station_output_haul(
            &mut colony,
            &building,
            0,
            ResourceKind::Tools,
            production_gate(1, 1_000),
        ));
        assert_eq!(
            colony.items.instance(&tool_id).unwrap().location,
            ItemLocation::Carrier {
                cat_id: cat_id.clone()
            }
        );
        assert_eq!(colony.resources.tools, 0.0);
        deliver_station_cargo_to_current_target(&mut colony);
        reconcile_finite_equipment_projections(&mut colony);
        let stored_pile = match &colony.items.instance(&tool_id).unwrap().location {
            ItemLocation::Stockpile { stockpile_id } => stockpile_id.clone(),
            location => panic!("crafted identity was not stored: {location:?}"),
        };
        assert_eq!(colony.items.count_kind(ItemKind::Tool), 1);
        assert_eq!(colony.items.credited_count(ItemKind::Tool), 1);
        assert_eq!(colony.resources.tools, 1.0);
        assert_eq!(
            colony
                .stockpiles
                .iter()
                .find(|pile| pile.id == stored_pile)
                .unwrap()
                .contents
                .tools,
            1.0
        );

        // A persistence boundary cannot allocate a replacement id or duplicate its
        // pile projection.
        let items_json = serde_json::to_string(&colony.items).unwrap();
        let piles_json = serde_json::to_string(&colony.stockpiles).unwrap();
        colony.items = serde_json::from_str(&items_json).unwrap();
        colony.stockpiles = serde_json::from_str(&piles_json).unwrap();
        reconcile_colony_stockpiles(&mut colony);
        assert_eq!(colony.items.count_kind(ItemKind::Tool), 1);
        assert_eq!(
            colony.items.instance(&tool_id).unwrap().location,
            ItemLocation::Stockpile {
                stockpile_id: stored_pile.clone()
            }
        );

        // The station worker physically retrieves that exact id and equips it. The
        // owned scalar stays one while the pile loses its sole unit.
        let (x, y) = colony
            .stockpiles
            .iter()
            .find(|pile| pile.id == stored_pile)
            .unwrap()
            .center();
        colony.cats[0].position = position_from_world(WorldPos { x, y });
        colony.cats[0].activity = CatActivity::Idle;
        colony.cats[0].carrying = None;
        colony.cats[0].destination = None;
        retrieve_automatic_functional_equipment(&mut colony, 2_000);
        assert_eq!(
            colony.items.instance(&tool_id).unwrap().location,
            ItemLocation::Carrier {
                cat_id: cat_id.clone()
            }
        );
        complete_equipment_retrieval(&mut colony, &cat_id, &tool_id);
        reconcile_finite_equipment_projections(&mut colony);
        assert_eq!(
            colony.items.instance(&tool_id).unwrap().location,
            ItemLocation::Equipped {
                cat_id: cat_id.clone()
            }
        );
        assert_eq!(colony.resources.tools, 1.0);
        assert_eq!(
            colony
                .stockpiles
                .iter()
                .map(|pile| pile.contents.tools)
                .sum::<f64>(),
            0.0
        );

        // Exact use wears this id to broken; no other Tool identity exists to absorb
        // condition loss.
        let maximum = colony.items.instance(&tool_id).unwrap().max_durability;
        for use_index in 0..maximum {
            wear_equipped_item(
                &mut colony,
                &cat_id,
                ItemKind::Tool,
                3_000 + i64::from(use_index),
            );
        }
        assert!(colony.items.instance(&tool_id).unwrap().is_broken());
        assert_eq!(colony.items.count_kind(ItemKind::Tool), 1);

        let mut world = WorldState {
            shared_spatial: Default::default(),
            world_seed: 123,
            colonies: vec![colony],
        };
        let action_ctx = |now_ms| ActionCtx {
            session_id: "exact-lifecycle-session".to_owned(),
            player_id: "exact-lifecycle-player".to_owned(),
            colony_id: "colony-1".to_owned(),
            now_ms,
        };
        let unequip = proto::ClientAction::UnequipItem {
            session_id: "exact-lifecycle-session".to_owned(),
            nickname: "Lifecycle Tester".to_owned(),
            sig: "signed".to_owned(),
            cat_id: cat_id.clone(),
            item_id: tool_id.clone(),
        };
        assert!(apply_action(&mut world, &unequip, &action_ctx(4_000)).ok);
        let ItemLocation::Stockpile { stockpile_id } =
            &world.colonies[0].items.instance(&tool_id).unwrap().location
        else {
            panic!("capacity-aware unequip did not return the exact id to storage");
        };
        assert!(
            world.colonies[0]
                .stockpiles
                .iter()
                .any(|pile| pile.id == *stockpile_id)
        );
        assert_equipment_piles_within_capacity(&world.colonies[0]);

        let repair = proto::ClientAction::RepairItem {
            session_id: "exact-lifecycle-session".to_owned(),
            nickname: "Lifecycle Tester".to_owned(),
            sig: "signed".to_owned(),
            item_id: tool_id.clone(),
        };
        let repaired = apply_action(&mut world, &repair, &action_ctx(5_000));
        assert!(repaired.ok, "repair failed: {repaired:?}");
        assert!(
            world.colonies[0]
                .items
                .instance(&tool_id)
                .unwrap()
                .is_pristine()
        );

        // The pristine exact identity finally crosses to the trader. Colony scalar
        // and piles both fall to zero while the trader owns that same stable id.
        world.colonies[0].trader = Some(TraderRuntime {
            id: "lifecycle-trader".to_owned(),
            position: Position::default(),
            destination: None,
            state: trader::TraderState::Trading,
            arrived_at: Some(5_000),
            depart_at: Some(10_000),
            route_exterior: None,
            visit_destination: None,
            route_blocked: false,
            visit_number: 1,
            stock: BTreeMap::new(),
            items: ItemStore::default(),
            coin: 10_000.0,
        });
        let sale = proto::ClientAction::SellGoods {
            session_id: "exact-lifecycle-session".to_owned(),
            nickname: "Lifecycle Tester".to_owned(),
            sig: "signed".to_owned(),
            kind: "tool".to_owned(),
            material: "wood".to_owned(),
            quality: 1,
            count: 1,
        };
        let sold = apply_action(&mut world, &sale, &action_ctx(6_000));
        assert!(sold.ok, "sale failed: {sold:?}");
        let colony = &world.colonies[0];
        assert!(colony.items.instance(&tool_id).is_none());
        assert_eq!(colony.resources.tools, 0.0);
        assert_eq!(
            colony
                .stockpiles
                .iter()
                .map(|pile| pile.contents.tools)
                .sum::<f64>(),
            0.0
        );
        let sold_instance = colony
            .trader
            .as_ref()
            .unwrap()
            .items
            .instance(&tool_id)
            .expect("the same exact id reached the trader");
        assert_eq!(
            sold_instance.location,
            ItemLocation::Trader {
                trader_id: "lifecycle-trader".to_owned()
            }
        );
        assert_eq!(
            colony.items.count_kind(ItemKind::Tool)
                + colony
                    .trader
                    .as_ref()
                    .unwrap()
                    .items
                    .count_kind(ItemKind::Tool),
            1,
            "the lifecycle never duplicated or destroyed the one finite identity"
        );
    }

    #[test]
    fn physical_tool_retrieval_preserves_scalar_and_moves_one_exact_id() {
        let mut colony = chain_colony(BuildingType::Workshop, Resources::default(), true);
        colony.finite_equipment_rules_version = CURRENT_FINITE_EQUIPMENT_RULES_VERSION;
        let pile_id = colony
            .stockpiles
            .iter()
            .find(|pile| pile.is_general_storehouse())
            .unwrap()
            .id
            .clone();
        let worker_id = colony.cats[0].id.clone();
        let tool_id = colony
            .items
            .add_at(
                Item::new(ItemKind::Tool, Material::Wood, 1),
                1,
                1.0,
                ItemLocation::Stockpile {
                    stockpile_id: pile_id.clone(),
                },
                true,
            )
            .pop()
            .unwrap();
        reconcile_finite_equipment_projections(&mut colony);
        let (x, y) = colony
            .stockpiles
            .iter()
            .find(|pile| pile.id == pile_id)
            .unwrap()
            .center();
        colony.cats[0].position = position_from_world(WorldPos { x, y });

        retrieve_automatic_functional_equipment(&mut colony, 1_000);
        assert_eq!(
            colony.items.instance(&tool_id).unwrap().location,
            ItemLocation::Carrier {
                cat_id: worker_id.clone()
            }
        );
        assert_eq!(colony.resources.tools, 1.0, "ownership never flickers");
        reconcile_finite_equipment_projections(&mut colony);
        assert_eq!(
            colony
                .stockpiles
                .iter()
                .find(|pile| pile.id == pile_id)
                .unwrap()
                .contents
                .tools,
            0.0,
            "the carried identity is no longer also in storage"
        );

        complete_equipment_retrieval(&mut colony, &worker_id, &tool_id);
        assert_eq!(
            colony.items.instance(&tool_id).unwrap().location,
            ItemLocation::Equipped {
                cat_id: worker_id.clone()
            }
        );
        assert_eq!(colony.resources.tools, 1.0);
    }

