    #[test]
    fn founding_never_places_a_building_or_road_on_water() {
        // Across seeds, the water-clearing pass keeps every building and road tile dry,
        // while a reachable water source still exists for the fetch-water economy.
        for seed in [1234u32, 42, 7, 99, 555, 4242] {
            let colony = found_colony(seed, "colony-1", 1_000, seed);

            let mut blocked: HashSet<TilePos> = colony
                .buildings
                .iter()
                .flat_map(building_footprint_tiles)
                .collect();
            blocked.extend(founding_road_tiles(VILLAGE_ANCHOR_TILE));
            for pos in &blocked {
                assert!(
                    !tile_has_water(colony.world_tiles.get(pos)),
                    "seed {seed}: water under a building/road at {pos:?}"
                );
            }

            assert!(
                colony.world_tiles.values().any(|t| tile_has_water(Some(t))
                    && !colony.claimed_tiles.contains(&t.pos)
                    && cheb_from_anchor(VILLAGE_ANCHOR_TILE, t.pos) <= VILLAGE_START_RADIUS + 2),
                "seed {seed}: the village has no reachable water source"
            );
        }
    }

    // --- P16.x: founding craft-bench staffing (workshop-staffing bug regression) ---

    /// Run a founding colony with an already-appointed Forester through `world_tick`
    /// for 45 simulated minutes with no further player input
    /// simulated minutes (one-minute ticks; `test_time_scale` defaults to 1.0 so this is
    /// 2700 real/production seconds — four-plus full 600s workshop cycles of headroom
    /// past the very first tick, which is when the fix staffs a bench). Returns the
    /// final colony plus whether planks and blocks were ever simultaneously banked
    /// (`> 0.0`) at the end of some tick during the run.
    ///
    /// 45 ticks is a deliberately snug window, not just "long enough": without the fix,
    /// the founding stall isn't perfectly permanent — once a *short* `explore` job
    /// finishes it can incidentally free a cat for phase 23's pre-existing mop-up, and
    /// empirically (seed 4242) that eventually produces both planks and blocks by tick
    /// ~54. A 60-tick window would pass either way and prove nothing; 45 sits above the
    /// fix's own bootstrap (both banked by tick ~32) but below that incidental-healing
    /// floor, so this test actually discriminates "staffed promptly by the fix" from
    /// "eventually self-healed by an unrelated mechanic."
    ///
    /// The end-of-run snapshot alone is also not a reliable enough signal: the
    /// woodworking bench is a "luxury tier" that spends 2 planks + 2 blocks per tool
    /// cycle once both are stocked (see `phase_23_production`'s `BuildingType::
    /// Woodworking` arm), so a founding colony's planks/blocks stock legitimately saws
    /// up and back down to 0 over time. Tracking "ever banked both simultaneously"
    /// proves the craft benches were staffed and produced, without being sensitive to
    /// which exact tick the woodworking bench next drains the stockpile.
    fn run_forester_colony_for_45_minutes(seed: u32) -> (ColonyRuntime, bool) {
        let mut world = new_world(seed);
        world
            .colonies
            .push(found_colony(world.world_seed, "colony-1", 10_000, seed));
        establish_office(&mut world.colonies[0], OfficerRole::Forester);

        let mut banked_planks_and_blocks = false;
        for step in 1..=45 {
            let now = 10_000 + i64::from(step) * 60_000;
            let reports = world_tick(&mut world, now);
            assert_eq!(reports[0].reset_reason, None, "step {step}: colony reset");
            let resources = &world.colonies[0].resources;
            if resources.planks > 0.0 && resources.blocks > 0.0 {
                banked_planks_and_blocks = true;
            }
        }

        (world.colonies.remove(0), banked_planks_and_blocks)
    }

    #[test]
    fn forester_staffs_a_craft_bench_on_the_first_tick_while_a_vacancy_stays_manual() {
        let mut world = new_world(4242);
        world
            .colonies
            .push(found_colony(world.world_seed, "colony-1", 10_000, 4242));
        let _ = world_tick(&mut world, 70_000);

        assert!(
            world.colonies[0]
                .buildings
                .iter()
                .filter(|building| RAW_MATERIAL_WORKSHOPS.contains(&building.building_type))
                .all(|building| building.assigned_cat.is_none()),
            "a vacant Forester role must leave raw-material staffing to the player"
        );

        establish_office(&mut world.colonies[0], OfficerRole::Forester);
        let _ = world_tick(&mut world, 130_000);
        assert!(
            world.colonies[0]
                .buildings
                .iter()
                .filter(|building| RAW_MATERIAL_WORKSHOPS.contains(&building.building_type))
                .all(|building| building.assigned_cat.is_none()),
            "a filled Forester office stays dormant while the founding larder is below comfort"
        );

        let population = active_resident_cats(&world.colonies[0]).count() as f64;
        let food_boundary =
            (population * RESEARCH_COMFORT_FOOD_PER_CAT).max(RESEARCH_COMFORT_FLOOR);
        let water_boundary =
            (population * RESEARCH_COMFORT_WATER_PER_CAT).max(RESEARCH_COMFORT_FLOOR);
        world.colonies[0].resources.food = food_boundary;
        world.colonies[0].resources.water = water_boundary;
        assert!(raw_chain_survival_reserve_met(&world.colonies[0]));
        // Phase 7 consumes before phase 23 staffs; fund that one-minute tick so
        // the resources are still at the exact boundary when the Forester acts.
        world.colonies[0].resources.food += 1.0;
        world.colonies[0].resources.water += 1.0;
        reconcile_colony_stockpiles(&mut world.colonies[0]);
        let _ = world_tick(&mut world, 190_000);

        let staffed_benches = world.colonies[0]
            .buildings
            .iter()
            .filter(|building| {
                matches!(
                    building.building_type,
                    BuildingType::WoodCutter | BuildingType::StonePrep | BuildingType::Woodworking
                ) && building.assigned_cat.is_some()
            })
            .count();
        assert!(
            staffed_benches >= 1,
            "expected at least one craft bench staffed after the first tick, got {staffed_benches}"
        );
    }

    #[test]
    fn non_sticky_raw_benches_restaff_and_repair_under_competing_labor() {
        let seed = 4_242;
        let mut world = new_world(seed);
        let mut colony = found_colony(seed, "colony-1", 10_000, seed);
        provision_established_roster(&mut colony, 20);
        colony.resources.food = 200.0;
        colony.resources.water = 200.0;
        colony.resources.materials = 25.0;
        colony.resources.stone = 25.0;
        colony.resources.logs = 25.0;
        colony.resources.planks = 2.0;
        colony.resources.blocks = 1.0;
        establish_office(&mut colony, OfficerRole::Forester);
        establish_office(&mut colony, OfficerRole::Farmer);
        establish_office(&mut colony, OfficerRole::Loremaster);

        // Reproduce the stale-snapshot edge: every non-sticky bench enters the
        // first tick with a persisted worker, while the leader still has ordinary
        // hunt/scout/quarry employment to allocate. Releasing only inside phase 20
        // would make phase 18 report zero open craft stations for this tick.
        let worker_ids = colony
            .cats
            .iter()
            .take(RAW_MATERIAL_WORKSHOPS.len())
            .map(|cat| cat.id.clone())
            .collect::<Vec<_>>();
        for (bench_type, worker_id) in RAW_MATERIAL_WORKSHOPS.into_iter().zip(worker_ids) {
            let worker = colony
                .cats
                .iter_mut()
                .find(|cat| cat.id == worker_id)
                .expect("bench worker exists");
            worker.activity = CatActivity::Working;
            worker.current_task = Some(TaskType::Build);
            let bench = colony
                .buildings
                .iter_mut()
                .find(|building| building.building_type == bench_type)
                .expect("founding raw bench exists");
            bench.assigned_cat = Some(worker_id);
            bench.automated_by = Some(OfficerRole::Forester);
            bench.production_progress = 590.0;
        }
        world.colonies.push(colony);

        let mut saw_competing_job = false;
        let mut saw_staffed_while_deficient = false;
        let mut repaired_both_buffers = false;
        for step in 1..=60 {
            let now = 10_000 + i64::from(step) * 60_000;
            let report = world_tick(&mut world, now);
            assert_eq!(report[0].reset_reason, None, "step {step}: colony reset");
            let colony = &world.colonies[0];
            let staffed_raw = colony
                .buildings
                .iter()
                .filter(|building| {
                    RAW_MATERIAL_WORKSHOPS.contains(&building.building_type)
                        && building.assigned_cat.is_some()
                })
                .count();
            if colony.resources.planks >= TOOL_BUILD_MATERIAL_RESERVE
                && colony.resources.blocks >= TOOL_BUILD_MATERIAL_RESERVE
            {
                repaired_both_buffers = true;
            }
            if !repaired_both_buffers {
                saw_staffed_while_deficient |= staffed_raw > 0;
            }
            saw_competing_job |= active_or_queued_jobs(colony).iter().any(|job| {
                matches!(
                    job.kind,
                    JobKind::HuntExpedition | JobKind::Explore | JobKind::Quarry
                )
            });
            if repaired_both_buffers && saw_competing_job && saw_staffed_while_deficient {
                break;
            }
        }

        let colony = &world.colonies[0];
        assert!(saw_competing_job, "fixture never exercised competing labor");
        assert!(
            saw_staffed_while_deficient,
            "deficient raw buffers never restaffed a bench"
        );
        assert!(
            repaired_both_buffers,
            "the two raw buffers never repaired: resources={:?}, raw={:?}, station={:?}, cargo={:?}",
            colony.resources,
            colony
                .buildings
                .iter()
                .filter(|building| RAW_MATERIAL_WORKSHOPS.contains(&building.building_type))
                .map(|building| (
                    building.building_type,
                    &building.assigned_cat,
                    building.production_progress
                ))
                .collect::<Vec<_>>(),
            colony
                .stockpiles
                .iter()
                .filter(|pile| pile.is_station_local())
                .map(|pile| (&pile.id, &pile.contents))
                .collect::<Vec<_>>(),
            colony
                .cats
                .iter()
                .filter_map(|cat| cat.carrying.as_ref().map(|cargo| (&cat.id, cargo)))
                .collect::<Vec<_>>()
        );
        assert!(
            colony.resources.planks >= TOOL_BUILD_MATERIAL_RESERVE
                && colony.resources.planks
                    <= TOOL_BUILD_MATERIAL_RESERVE + crate::production::WOODCUTTER_PLANKS_PER_CYCLE,
            "physical batches may finish at most one unit beyond the exact reserve"
        );
        assert!(
            colony.resources.blocks >= TOOL_BUILD_MATERIAL_RESERVE
                && colony.resources.blocks
                    <= TOOL_BUILD_MATERIAL_RESERVE + crate::production::STONEPREP_BLOCKS_PER_CYCLE,
            "physical batches may finish at most one unit beyond the exact reserve"
        );
        assert_eq!(
            colony.resources.materials, 25.0,
            "physical Wood Cutter consumes Logs, never generic Supplies"
        );
        assert!(
            colony.resources.stone >= 10.0,
            "the bench repairs Blocks without erasing independently quarried raw Stone"
        );
    }

    #[test]
    fn legacy_orphaned_working_cat_is_reconciled_without_releasing_committed_workers() {
        let mut colony = found_colony(4_242, "colony-1", 10_000, 4_242);
        colony.jobs.clear();
        let orphan = colony.cats[0].id.clone();
        let building_worker = colony.cats[1].id.clone();
        let job_worker = colony.cats[2].id.clone();
        for cat_id in [&orphan, &building_worker, &job_worker] {
            let cat = colony
                .cats
                .iter_mut()
                .find(|cat| cat.id == *cat_id)
                .expect("fixture cat exists");
            cat.activity = CatActivity::Working;
            cat.current_task = Some(TaskType::Build);
        }
        colony
            .buildings
            .iter_mut()
            .find(|building| building.building_type == BuildingType::Den)
            .expect("founding den exists")
            .assigned_cat = Some(building_worker.clone());
        colony.jobs.push(JobRuntime {
            id: "committed-job".to_owned(),
            kind: JobKind::BuildHouse,
            status: JobStatus::Active,
            assigned_cat: Some(job_worker.clone()),
            ..JobRuntime::default()
        });

        release_raw_material_workshop_workers(&mut colony);

        let cat = |id: &str| colony.cats.iter().find(|cat| cat.id == id).unwrap();
        assert_eq!(cat(&orphan).activity, CatActivity::Idle);
        assert_eq!(cat(&orphan).current_task, None);
        assert_eq!(cat(&building_worker).activity, CatActivity::Working);
        assert_eq!(cat(&job_worker).activity, CatActivity::Working);
    }

    #[test]
    fn automated_wood_cutter_keeps_one_worker_through_fetch_work_and_output_delivery() {
        let mut colony = chain_colony(
            BuildingType::WoodCutter,
            Resources {
                logs: crate::production::WOODCUTTER_LOGS_PER_CYCLE,
                ..Resources::default()
            },
            true,
        );
        colony.buildings[0].automated_by = Some(OfficerRole::Forester);
        colony.buildings[0].production_progress = 0.0;
        let worker_id = colony.buildings[0].assigned_cat.clone().unwrap();
        place_chain_worker_at_seeded_store(&mut colony);

        phase_23_production(&mut colony, production_gate(1, 1_000), 123);
        assert_eq!(
            colony.cats[0].carrying.as_ref().unwrap().kind,
            CarryingKind::Logs
        );
        release_raw_material_workshop_workers(&mut colony);
        release_raw_material_workshop_workers(&mut colony);
        assert_eq!(
            colony.buildings[0].assigned_cat.as_deref(),
            Some(worker_id.as_str())
        );

        deliver_station_cargo_to_current_target(&mut colony);
        phase_23_production(&mut colony, production_gate(600, 601_000), 123);
        assert_eq!(
            building_station_inventory(&colony, &colony.buildings[0], true),
            [(ResourceKind::Planks, 1.0)]
        );
        release_raw_material_workshop_workers(&mut colony);
        assert_eq!(
            colony.buildings[0].assigned_cat.as_deref(),
            Some(worker_id.as_str())
        );

        phase_23_production(&mut colony, production_gate(1, 602_000), 123);
        assert_eq!(
            colony.cats[0].carrying.as_ref().unwrap().kind,
            CarryingKind::Planks
        );
        let before_progress = colony.buildings[0].production_progress;
        release_raw_material_workshop_workers(&mut colony);
        phase_23_production(&mut colony, production_gate(600, 1_202_000), 123);
        assert_eq!(
            colony.buildings[0].assigned_cat.as_deref(),
            Some(worker_id.as_str())
        );
        assert_eq!(colony.buildings[0].production_progress, before_progress);
        assert_eq!(
            building_station_inventory(&colony, &colony.buildings[0], true),
            Vec::<(ResourceKind, f64)>::new(),
            "no second worker may create output while the assigned cat hauls"
        );
    }

    #[test]
    fn paused_or_empty_automated_physical_raw_bench_releases_worker_without_losing_local_inputs() {
        for (building_type, resources, input_kind) in [
            (
                BuildingType::WoodCutter,
                Resources {
                    logs: crate::production::WOODCUTTER_LOGS_PER_CYCLE,
                    ..Resources::default()
                },
                ResourceKind::Logs,
            ),
            (
                BuildingType::StonePrep,
                Resources {
                    stone: crate::production::STONEPREP_STONE_PER_CYCLE,
                    ..Resources::default()
                },
                ResourceKind::Stone,
            ),
        ] {
            let mut base = chain_colony(building_type, resources, true);
            base.buildings[0].automated_by = Some(OfficerRole::Forester);
            base.buildings[0].production_progress = 300.0;
            ensure_station_stores(&mut base, 0);
            let input_id = stockpiles::station_input_id(&base.buildings[0].id);
            stockpiles::set_resource(
                &mut base
                    .stockpiles
                    .iter_mut()
                    .find(|pile| pile.id == input_id)
                    .unwrap()
                    .contents,
                input_kind,
                5.0,
            );

            for (label, mut colony) in [
                ("paused", {
                    let mut colony = base.clone();
                    colony.buildings[0].production_paused = true;
                    colony
                }),
                ("empty", {
                    let mut colony = base.clone();
                    colony.buildings[0].production_queue.clear();
                    colony
                }),
            ] {
                let input_before = building_station_inventory(&colony, &colony.buildings[0], false);
                let output_before = building_station_inventory(&colony, &colony.buildings[0], true);
                let progress_before = colony.buildings[0].production_progress;

                release_raw_material_workshop_workers(&mut colony);

                assert_eq!(
                    colony.buildings[0].assigned_cat, None,
                    "{building_type:?} {label}"
                );
                assert_eq!(
                    colony.buildings[0].automated_by, None,
                    "{building_type:?} {label}"
                );
                assert_eq!(
                    colony.buildings[0].production_progress, progress_before,
                    "{building_type:?} {label}"
                );
                assert_eq!(
                    building_station_inventory(&colony, &colony.buildings[0], false),
                    input_before,
                    "{building_type:?} {label}"
                );
                assert_eq!(
                    building_station_inventory(&colony, &colony.buildings[0], true),
                    output_before,
                    "{building_type:?} {label}"
                );
            }
        }
    }

