    #[test]
    fn water_preemption_queues_one_real_fetch_and_waits_for_its_returner() {
        let mut colony = found_colony(4_242, "colony-1", 10_000, 4_242);
        colony.jobs.clear();
        colony.resources.water = 0.0;
        let scout = colony.cats[0].id.clone();
        colony.jobs.push(JobRuntime {
            id: "ghost-fetch".to_owned(),
            kind: JobKind::FetchWater,
            status: JobStatus::Queued,
            assigned_cat: None,
            ..JobRuntime::default()
        });
        colony.jobs.push(general_scout_job(
            "leader-scout",
            &scout,
            JobRequester::Leader,
        ));

        phase_17b_water_reserve_preemption(&mut colony, production_gate(1, 11_000));
        phase_17b_water_reserve_preemption(&mut colony, production_gate(1, 12_000));
        let real_fetches = colony
            .jobs
            .iter()
            .filter(|job| {
                job.kind == JobKind::FetchWater
                    && matches!(job.status, JobStatus::Active | JobStatus::Queued)
                    && job.assigned_cat.as_deref() == Some(scout.as_str())
            })
            .count();
        assert_eq!(
            real_fetches, 1,
            "the unassigned ghost never blocks or duplicates work"
        );

        let real_fetch = colony
            .jobs
            .iter_mut()
            .find(|job| {
                job.kind == JobKind::FetchWater
                    && job.assigned_cat.as_deref() == Some(scout.as_str())
            })
            .expect("real fetch exists");
        real_fetch.status = JobStatus::Completed;
        let carrier = colony
            .cats
            .iter_mut()
            .find(|cat| cat.id == scout)
            .expect("living carrier exists");
        carrier.activity = CatActivity::Returning;
        carrier.carrying = Some(Carrying {
            kind: CarryingKind::Water,
            amount: 10.0,
            job_ended_at: 12_000,
            source_gather_spot: None,
        });

        phase_17b_water_reserve_preemption(&mut colony, production_gate(1, 13_000));
        assert_eq!(
            colony
                .jobs
                .iter()
                .filter(|job| {
                    job.kind == JobKind::FetchWater
                        && job.assigned_cat.as_deref() == Some(scout.as_str())
                })
                .count(),
            1,
            "a physical water returner suppresses replacement dispatch"
        );
    }

    #[test]
    fn water_preemption_scales_committed_fetchers_to_deficit_without_exceeding_cap() {
        let mut colony = found_colony(4_242, "colony-1", 10_000, 4_242);
        colony.jobs.clear();
        colony.resources.water = 0.0;
        let template = colony.cats[0].clone();
        for index in 0..13 {
            let mut cat = template.clone();
            cat.id = format!("grown-water-cat-{index}");
            cat.name = format!("Water Cat {index}");
            cat.current_task = None;
            cat.activity = CatActivity::Idle;
            cat.destination = None;
            cat.carrying = None;
            colony.cats.push(cat);
        }
        assert_eq!(alive_cats(&colony.cats).count(), 28);

        let active_fetcher = colony.cats[0].id.clone();
        colony.jobs.push(JobRuntime {
            id: "existing-fetch".to_owned(),
            kind: JobKind::FetchWater,
            status: JobStatus::Active,
            requested_by: JobRequester::Leader,
            assigned_cat: Some(active_fetcher),
            ..JobRuntime::default()
        });
        let returner_id = colony.cats[1].id.clone();
        let returner = colony
            .cats
            .iter_mut()
            .find(|cat| cat.id == returner_id)
            .expect("water returner exists");
        returner.activity = CatActivity::Returning;
        returner.carrying = Some(Carrying {
            kind: CarryingKind::Water,
            amount: 10.0,
            job_ended_at: 10_000,
            source_gather_spot: None,
        });
        colony.jobs.push(JobRuntime {
            id: "returner-fetch".to_owned(),
            kind: JobKind::FetchWater,
            status: JobStatus::Active,
            requested_by: JobRequester::Leader,
            assigned_cat: Some(returner_id.clone()),
            ..JobRuntime::default()
        });
        let mut dead_ghost = template.clone();
        dead_ghost.id = "dead-fetch-ghost".to_owned();
        dead_ghost.death_time = Some(10_500);
        colony.cats.push(dead_ghost);
        colony.jobs.extend([
            JobRuntime {
                id: "dead-fetch".to_owned(),
                kind: JobKind::FetchWater,
                status: JobStatus::Active,
                requested_by: JobRequester::Leader,
                assigned_cat: Some("dead-fetch-ghost".to_owned()),
                ..JobRuntime::default()
            },
            JobRuntime {
                id: "unassigned-fetch".to_owned(),
                kind: JobKind::FetchWater,
                status: JobStatus::Queued,
                requested_by: JobRequester::Leader,
                assigned_cat: None,
                ..JobRuntime::default()
            },
        ]);
        let scouts = [colony.cats[2].id.clone(), colony.cats[3].id.clone()];
        for (index, scout) in scouts.iter().enumerate() {
            colony.jobs.push(general_scout_job(
                &format!("reserve-scout-{index}"),
                scout,
                JobRequester::Leader,
            ));
        }

        assert_eq!(desired_water_fetcher_count(28, 0.0), 4);
        assert_eq!(
            committed_water_fetcher_count(&colony),
            2,
            "the active fetch and returning carrier are each counted once"
        );
        phase_17b_water_reserve_preemption(&mut colony, production_gate(1, 11_000));
        assert_eq!(committed_water_fetcher_count(&colony), 3);
        phase_17b_water_reserve_preemption(&mut colony, production_gate(1, 12_000));
        assert_eq!(committed_water_fetcher_count(&colony), 4);
        phase_17b_water_reserve_preemption(&mut colony, production_gate(1, 13_000));
        assert_eq!(
            committed_water_fetcher_count(&colony),
            WATER_MAX_SLOTS as usize,
            "the deficit scheduler never exceeds the director's water cap"
        );
        let fetcher_ids = colony
            .jobs
            .iter()
            .filter(|job| {
                job.kind == JobKind::FetchWater
                    && matches!(job.status, JobStatus::Active | JobStatus::Queued)
            })
            .filter_map(|job| job.assigned_cat.as_deref())
            .filter(|cat_id| {
                colony
                    .cats
                    .iter()
                    .any(|cat| cat.id == **cat_id && cat.death_time.is_none())
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(fetcher_ids.len(), 4, "no cat receives duplicate fetch jobs");
    }

    #[test]
    fn emergency_preemption_chooses_luxury_work_and_preserves_field_and_mill() {
        let cats = ["field-cat", "mill-cat", "ledger-cat"]
            .into_iter()
            .map(|id| adult_idle_cat(id, "colony-1"))
            .collect::<Vec<_>>();
        let staffed = |id: &str, building_type: BuildingType, cat_id: &str| BuildingRuntime {
            id: id.to_owned(),
            building_type,
            is_complete: true,
            construction_progress: 100,
            assigned_cat: Some(cat_id.to_owned()),
            automated_by: Some(match building_type {
                BuildingType::Field | BuildingType::Mill => OfficerRole::Farmer,
                BuildingType::AccountingTent => OfficerRole::Accountant,
                _ => unreachable!("fixture uses only Farmer and Accountant stations"),
            }),
            ..BuildingRuntime::default()
        };
        let mut colony = ColonyRuntime {
            id: "colony-1".to_owned(),
            cats,
            buildings: vec![
                staffed("field", BuildingType::Field, "field-cat"),
                staffed("mill", BuildingType::Mill, "mill-cat"),
                staffed("accounting", BuildingType::AccountingTent, "ledger-cat"),
            ],
            ..ColonyRuntime::default()
        };

        assert_eq!(
            select_best_preemptible_production_worker(&colony, None, EmergencyResource::Water,)
                .as_deref(),
            Some("ledger-cat"),
            "luxury accounting work is reclaimed before either food producer"
        );
        colony.buildings.pop();
        assert_eq!(
            select_best_preemptible_production_worker(&colony, None, EmergencyResource::Water,),
            None,
            "Field and Mill workers are not eligible emergency-preemption targets"
        );
        assert!(
            matches!(
                select_best_preemptible_production_worker(&colony, None, EmergencyResource::Food,)
                    .as_deref(),
                Some("field-cat" | "mill-cat")
            ),
            "an empty larder may reclaim food-production labor for a larger hunt yield"
        );
        assert_eq!(
            colony.buildings[0].assigned_cat.as_deref(),
            Some("field-cat")
        );
        assert_eq!(
            colony.buildings[1].assigned_cat.as_deref(),
            Some("mill-cat")
        );
    }

    #[test]
    fn leader_cancellation_never_cancels_player_hunts_or_training() {
        let mut colony = found_colony(44, "colony-1", 1_000, 44);
        colony.jobs.clear();
        for (id, kind, requested_by) in [
            ("leader-hunt", JobKind::HuntExpedition, JobRequester::Leader),
            ("player-hunt", JobKind::HuntExpedition, JobRequester::Player),
            (
                "leader-training",
                JobKind::TrainWarrior,
                JobRequester::Leader,
            ),
            (
                "player-training",
                JobKind::TrainWarrior,
                JobRequester::Player,
            ),
        ] {
            colony.jobs.push(JobRuntime {
                id: id.to_owned(),
                kind,
                status: JobStatus::Active,
                requested_by,
                ..JobRuntime::default()
            });
        }

        assert_eq!(
            cancel_jobs(&mut colony, 2_000, JobKind::HuntExpedition, true),
            1
        );
        assert_eq!(
            cancel_jobs(&mut colony, 2_000, JobKind::TrainWarrior, false),
            1
        );
        let status = |id: &str| {
            colony
                .jobs
                .iter()
                .find(|job| job.id == id)
                .expect("fixture job exists")
                .status
        };
        assert_eq!(status("leader-hunt"), JobStatus::Cancelled);
        assert_eq!(status("leader-training"), JobStatus::Cancelled);
        assert_eq!(status("player-hunt"), JobStatus::Active);
        assert_eq!(status("player-training"), JobStatus::Active);
    }

    #[test]
    fn empty_larder_releases_three_automated_food_workers_for_urgent_hunts() {
        use crate::leader_director::OpenSlots;

        let mut colony = found_colony(43, "colony-1", 1_000, 43);
        establish_office(&mut colony, OfficerRole::Farmer);
        colony.jobs.clear();
        colony.resources.food = 0.0;
        colony.resources.water = 100.0;
        for building in &mut colony.buildings {
            building.assigned_cat = None;
            building.automated_by = None;
        }
        let existing_field = colony
            .buildings
            .iter()
            .find(|building| building.building_type == BuildingType::Field)
            .expect("Farmer prerequisite provides a field")
            .id
            .clone();
        let mill =
            install_completed_fixture_building(&mut colony, "food-crisis-mill", BuildingType::Mill);
        let second_field = install_completed_fixture_building(
            &mut colony,
            "food-crisis-field",
            BuildingType::Field,
        );
        let worker_ids = colony
            .cats
            .iter()
            .take(3)
            .map(|cat| cat.id.clone())
            .collect::<Vec<_>>();
        for (building_id, cat_id) in [existing_field, mill, second_field]
            .into_iter()
            .zip(&worker_ids)
        {
            let building = colony
                .buildings
                .iter_mut()
                .find(|building| building.id == building_id)
                .expect("food workplace exists");
            building.assigned_cat = Some(cat_id.clone());
            building.automated_by = Some(OfficerRole::Farmer);
        }
        let hunter = colony.cats[3].id.clone();
        let quarrier = colony.cats[4].id.clone();
        queue_job(
            &mut colony,
            1_000,
            JobKind::HuntExpedition,
            Some(hunter),
            JobMetadata::None,
        );
        queue_job(
            &mut colony,
            1_000,
            JobKind::Quarry,
            Some(quarrier),
            JobMetadata::None,
        );
        let plan = DirectorPlan {
            decisions: Vec::new(),
            slots: vec![OpenSlots {
                goal: LaborGoalKind::Hunt,
                count: 3,
                score: 1.0,
            }],
        };

        phase_20_leader_labor_assignments_and_staffing(
            &mut colony,
            production_gate(1, 2_000),
            reliable_policy(),
            &plan,
            43,
        );

        assert_eq!(
            active_or_queued_jobs(&colony)
                .iter()
                .filter(|job| job.kind == JobKind::HuntExpedition)
                .count(),
            4,
            "the existing hunt plus three reclaimed food workers all remain staffed"
        );
        assert!(colony.buildings.iter().all(|building| {
            !matches!(
                building.building_type,
                BuildingType::Field | BuildingType::Mill
            ) || building.automated_by != Some(OfficerRole::Farmer)
        }));
    }

