    fn shrine_action_ctx(now_ms: i64) -> ActionCtx {
        ActionCtx {
            session_id: "shrine-session".to_owned(),
            player_id: "shrine-player".to_owned(),
            colony_id: "colony-1".to_owned(),
            now_ms,
        }
    }

    fn signed_shrine_action(action: &str, node_id: Option<&str>) -> proto::ClientAction {
        let session_id = "shrine-session".to_owned();
        let nickname = "Shrine Tester".to_owned();
        let sig = "pure-sim".to_owned();
        match action {
            "tithe" => proto::ClientAction::OfferTithe {
                session_id,
                nickname,
                sig,
            },
            "materials" => proto::ClientAction::OfferMaterials {
                session_id,
                nickname,
                sig,
            },
            "unlock" => proto::ClientAction::UnlockNode {
                session_id,
                nickname,
                sig,
                node_id: node_id.expect("unlock action needs a node").to_owned(),
            },
            "research" => proto::ClientAction::ResearchNode {
                session_id,
                nickname,
                sig,
                node_id: node_id.expect("research action needs a node").to_owned(),
            },
            _ => panic!("unknown shrine action {action}"),
        }
    }

    fn offering_job(colony: &mut ColonyRuntime) -> JobRuntime {
        let escrow_id = format!("{}offering-test", stockpiles::STATION_INPUT_PREFIX);
        let amount = f64::from(OFFERING_MATERIALS_AMOUNT);
        let source = colony
            .stockpiles
            .iter_mut()
            .find(|pile| {
                !pile.is_station_local()
                    && stockpiles::resource_amount(&pile.contents, ResourceKind::Materials)
                        >= amount
            })
            .expect("fixture has a visible material source");
        stockpiles::add_resource(&mut source.contents, ResourceKind::Materials, -amount);
        ensure_offering_escrow(colony, &escrow_id, ResourceKind::Materials);
        let escrow = colony
            .stockpiles
            .iter_mut()
            .find(|pile| pile.id == escrow_id)
            .expect("offering escrow exists");
        stockpiles::add_resource(&mut escrow.contents, ResourceKind::Materials, amount);
        JobRuntime {
            id: "job-offering-1".to_owned(),
            kind: JobKind::PerformOffering,
            status: JobStatus::Active,
            requested_by: JobRequester::Leader,
            assigned_cat: Some(colony.cats[0].id.clone()),
            duration_ms: 2_400_000,
            speed: 1.0,
            yield_amount: 1.0,
            click_count: 0,
            created_at: 0,
            started_at: Some(0),
            ends_at: Some(2_400_000),
            completed_at: None,
            metadata: JobMetadata::OfferingRitual {
                escrow_id,
                kind: ResourceKind::Materials,
                amount,
            },
        }
    }

