    #[test]
    fn each_selectable_offering_enforces_its_own_safe_reserve_and_amount() {
        for kind in OFFERING_RESOURCE_KINDS {
            let mut colony = offering_colony(0.0);
            add_complete_shrine(&mut colony);
            let reserve = offering_reserve(&colony, kind).unwrap();
            let amount = offering_amount(kind).unwrap();
            stockpiles::set_resource(&mut colony.resources, kind, reserve + amount - 0.01);
            reconcile_colony_stockpiles(&mut colony);
            let action = match kind {
                ResourceKind::Materials => signed_shrine_action("materials", None),
                ResourceKind::Food | ResourceKind::Herbs => proto::ClientAction::OfferResource {
                    session_id: "shrine-session".to_owned(),
                    nickname: "Shrine Tester".to_owned(),
                    sig: "signed-player-guidance".to_owned(),
                    resource: if kind == ResourceKind::Food {
                        proto::OfferingResource::Food
                    } else {
                        proto::OfferingResource::Herbs
                    },
                },
                _ => unreachable!(),
            };
            let mut world = WorldState {
                shared_spatial: Default::default(),
                world_seed: 7,
                colonies: vec![colony],
            };
            let rejected = apply_action(&mut world, &action, &shrine_action_ctx(1_000));
            assert!(!rejected.ok, "{kind:?} spent inside its reserve");

            stockpiles::set_resource(&mut world.colonies[0].resources, kind, reserve + amount);
            reconcile_colony_stockpiles(&mut world.colonies[0]);
            let accepted = apply_action(&mut world, &action, &shrine_action_ctx(1_001));
            assert!(
                accepted.ok,
                "{kind:?} exact safe threshold failed: {:?}",
                accepted.message
            );
        }
    }

    #[test]
    fn action_shrine_faucets_feed_spendable_fertility_balance_once_and_reset_preserves_it() {
        let mut colony = offering_colony(30.0);
        colony.resources.food = 200.0;
        colony.resources.refined = 10.0;
        // Prove the archived duplicate scalar is not the fertility input or HUD balance.
        colony.resources.blessings = 100.0;
        colony.global_upgrade_points = 5.0;
        colony.buildings.push(BuildingRuntime {
            id: "shrine".to_owned(),
            building_type: BuildingType::Shrine,
            is_complete: true,
            construction_progress: 100,
            ..BuildingRuntime::default()
        });
        let mut world = WorldState {
            shared_spatial: Default::default(),
            world_seed: 7,
            colonies: vec![colony],
        };

        let chance_at_five =
            conception_probability(None, fertility_blessing_balance(&world.colonies[0]), 1.0);
        assert_eq!(
            chance_at_five,
            conception_probability(None, 5.0, 1.0),
            "fertility reads the spendable balance, not resources.blessings"
        );

        let result = apply_action(
            &mut world,
            &signed_shrine_action("tithe", None),
            &shrine_action_ctx(1_000),
        );
        assert!(result.ok, "signed tithe failed: {:?}", result.message);
        assert_eq!(world.colonies[0].global_upgrade_points, 7.0);
        let chance_after_tithe =
            conception_probability(None, fertility_blessing_balance(&world.colonies[0]), 1.0);
        assert!(chance_after_tithe > chance_at_five);

        let result = apply_action(
            &mut world,
            &signed_shrine_action("materials", None),
            &shrine_action_ctx(2_000),
        );
        assert!(result.ok, "signed offering failed: {:?}", result.message);
        assert_eq!(
            world.colonies[0].global_upgrade_points, 7.0,
            "dispatch cannot credit a blessing before physical shrine delivery"
        );
        let carry_index = world.colonies[0]
            .jobs
            .iter()
            .position(|job| job.kind == JobKind::CarryOffering)
            .expect("action queued a material offering");
        let materials_before_pickup = world.colonies[0].resources.materials;
        phase_14_promote_queued_jobs_and_break_ground(
            &mut world.colonies[0],
            production_gate(1, 2_001),
            world.world_seed,
        );
        phase_15_assign_promoted_job_destinations(
            &mut world.colonies[0],
            production_gate(1, 2_001),
            world.world_seed,
        );
        let source_site = match world.colonies[0].jobs[carry_index].metadata {
            JobMetadata::OfferingCarry {
                site: Some(site), ..
            } => site,
            ref metadata => panic!("expected physical source metadata, got {metadata:?}"),
        };
        world.colonies[0].cats[0].position = position_from_world(tile_pos_to_world(source_site));
        accept_job(&mut world.colonies[0], carry_index, 2_002);
        advance_material_offering_logistics(&mut world.colonies[0], 2_002);
        assert_eq!(
            world.colonies[0].resources.materials,
            materials_before_pickup - f64::from(OFFERING_MATERIALS_AMOUNT),
            "pickup debits both the visible pile and aggregate ledger"
        );
        assert_eq!(world.colonies[0].global_upgrade_points, 7.0);
        assert_eq!(
            world.colonies[0].cats[0]
                .carrying
                .as_ref()
                .map(|cargo| cargo.kind),
            Some(CarryingKind::Materials)
        );

        world.colonies[0].cats[0].position =
            position_from_world(village_anchor_world(world.colonies[0].anchor));
        advance_material_offering_logistics(&mut world.colonies[0], 2_003);
        assert_eq!(
            world.colonies[0].resources.materials, materials_before_pickup,
            "shrine delivery persists the goods in escrow before ritual consumption"
        );
        assert_eq!(world.colonies[0].global_upgrade_points, 7.0);
        let ritual_index = world.colonies[0]
            .jobs
            .iter()
            .position(|job| job.kind == JobKind::PerformOffering)
            .expect("delivery queued the ritual stage");
        phase_14_promote_queued_jobs_and_break_ground(
            &mut world.colonies[0],
            production_gate(1, 2_004),
            world.world_seed,
        );
        world.colonies[0].jobs[ritual_index].ends_at = Some(2_005);
        phase_30_due_completion_build_ritual_training_return_mark_done(
            &mut world.colonies[0],
            production_gate(1, 2_005),
        );
        assert_eq!(
            world.colonies[0].resources.materials,
            materials_before_pickup - 10.0
        );
        assert_eq!(
            world.colonies[0].global_upgrade_points, 7.0,
            "ritual completion creates physical blessing cargo but does not credit it"
        );

        let gate = production_gate(1, 2_006);
        let mut movement = phase_32_movement_setup_and_village_expansion_queue(
            &mut world.colonies[0],
            gate,
            reliable_policy(),
            world.world_seed,
        );
        phase_33_movement_deposits_and_no_destination_wander(
            &mut world.colonies[0],
            gate,
            &mut movement,
        );
        assert_eq!(world.colonies[0].global_upgrade_points, 8.0);
        assert_eq!(world.colonies[0].cats[0].carrying, None);
        phase_33_movement_deposits_and_no_destination_wander(
            &mut world.colonies[0],
            gate,
            &mut movement,
        );
        assert_eq!(
            world.colonies[0].global_upgrade_points, 8.0,
            "a delivered offering must not be credited twice"
        );

        let before_spend =
            conception_probability(None, fertility_blessing_balance(&world.colonies[0]), 1.0);
        let result = apply_action(
            &mut world,
            &signed_shrine_action("unlock", Some("research_hut")),
            &shrine_action_ctx(3_000),
        );
        assert!(result.ok, "blessing purchase failed: {:?}", result.message);
        assert_eq!(world.colonies[0].global_upgrade_points, 3.0);
        let after_spend =
            conception_probability(None, fertility_blessing_balance(&world.colonies[0]), 1.0);
        assert_eq!(after_spend, conception_probability(None, 3.0, 1.0));
        assert!(after_spend < before_spend);

        world.colonies[0].upgrade_tree.research_points = 5.0;
        let result = apply_action(
            &mut world,
            &signed_shrine_action("research", Some("basic_tools")),
            &shrine_action_ctx(4_000),
        );
        assert!(
            result.ok,
            "cat research purchase failed: {:?}",
            result.message
        );
        assert_eq!(world.colonies[0].upgrade_tree.research_points, 0.0);
        assert_eq!(world.colonies[0].global_upgrade_points, 3.0);
        assert_eq!(
            conception_probability(None, fertility_blessing_balance(&world.colonies[0]), 1.0),
            after_spend,
            "cat research points are a distinct currency"
        );

        let snapshot = build_snapshot(&world, 4_000, 1);
        assert_eq!(snapshot.colonies[0].resources.blessings, 3.0);
        assert_eq!(snapshot.colonies[0].research.blessings, 3.0);

        for cat in &mut world.colonies[0].cats {
            cat.death_time = Some(5_000);
        }
        let mut twin = world.colonies[0].clone();
        reset_run(&mut world.colonies[0], 5_000, RunResetReason::AllCatsDead);
        reset_run(&mut twin, 5_000, RunResetReason::AllCatsDead);
        assert_eq!(world.colonies[0], twin, "reset must remain deterministic");
        assert_eq!(world.colonies[0].global_upgrade_points, 3.0);
        let snapshot = build_snapshot(&world, 5_000, 2);
        assert_eq!(snapshot.colonies[0].resources.blessings, 3.0);
        assert_eq!(snapshot.colonies[0].research.blessings, 3.0);
    }

    #[test]
    fn complete_offering_converts_surplus_materials_to_blessings_and_logs_an_event() {
        let mut colony = offering_colony(30.0);
        colony.buildings.push(BuildingRuntime {
            building_type: BuildingType::Shrine,
            is_complete: true,
            construction_progress: 100,
            ..BuildingRuntime::default()
        });
        let job = offering_job(&mut colony);

        assert!(complete_offering(
            &mut colony,
            &job,
            production_gate(60, 2_400_000)
        ));

        assert_eq!(
            colony.resources.materials, 20.0,
            "the documented OFFERING_MATERIALS_AMOUNT must be the amount consumed"
        );
        let carrying = colony.cats[0]
            .carrying
            .clone()
            .expect("the cat must be carrying the resulting blessings toward the shrine");
        assert_eq!(carrying.kind, CarryingKind::Blessings);
        assert_eq!(
            carrying.amount, 1.0,
            "ritual_mastery 0 -> exactly 1 blessing"
        );
        assert!(
            colony
                .events
                .iter()
                .any(|event| { event.kind == EventKind::Offering }),
            "expected an offering_performed event, got {:?}",
            colony.events
        );

        // The carry/credit step is fully reused, unchanged, from the Ritual path:
        // crediting the resulting carry converts it straight into blessings.
        let before = colony.global_upgrade_points;
        credit_carrying(
            &mut colony,
            &carrying,
            village_anchor_world(VILLAGE_ANCHOR_TILE),
        );
        assert_eq!(colony.global_upgrade_points, before + carrying.amount);
    }

